window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s7-1119","number":1119,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"لماذا ختم بـ﴿وما ظلمونا ولكن كانوا أنفسهم يظلمون﴾؟","answer":"نفى أن ينال ظلمهم الله، ثم أثبت أنهم كانوا يوقعون الضرر بأنفسهم؛ فوبال الكفر يعود إلى صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص727–750.","url":""}]},{"id":"s7-1120","number":1120,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"لماذا قدّم ﴿أنفسهم﴾ على ﴿يظلمون﴾؟","answer":"تقديم ﴿أنفسهم﴾ يفيد القصر والعناية: ما كانوا يظلمون إلا أنفسهم في الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص727–750.","url":""}]},{"id":"s7-1121","number":1121,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"لماذا جرت آية الأعراف أولًا بضمير الغيبة: ﴿وقطعناهم... وأوحينا... استسقاه قومه﴾، ثم التفتت إلى الخطاب: ﴿كلوا من طيبات ما رزقناكم﴾؟","answer":"بدأت القصة حكايةً عن أسلاف المخاطبين بضمير الغيبة، ثم التفتت إلى خطابهم في النعمة والتكليف ليشعر السامعون أنهم معنيون بالشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص469–471.","url":""}]},{"id":"s7-1122","number":1122,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"لماذا خوطب بنو إسرائيل في البقرة بقوله: ﴿وظللنا عليكم... وأنزلنا عليكم﴾، وحُكي عنهم في الأعراف بضمير الغيبة: ﴿وظللنا عليهم... وأنزلنا عليهم﴾؟","answer":"البقرة تخاطب بني إسرائيل مباشرة في مقام تعداد نعم الله عليهم، أما الأعراف فتسرد قصتهم للنبي ﷺ والأمة، فغلب فيها ضمير الغيبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص469–471.","url":""}]},{"id":"s7-1123","number":1123,"surah":7,"verses":[160],"verseLabel":"الأعراف: 160","question":"لماذا ذُكر في البقرة: ﴿كلوا واشربوا من رزق الله﴾، ولم يذكر الشرب في آية الأعراف؟","answer":"في البقرة ذُكر تفجر العيون فناسب أن يقال ﴿كلوا واشربوا﴾، أما الأعراف ففصل بين ذكر الماء والأمر بالطعام بنعم أخرى، فاكتفى بالأكل لدلالة السياق على الشرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص497–499.","url":""}]},{"id":"s7-1124","number":1124,"surah":7,"verses":[161],"verseLabel":"الأعراف: 161","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿وإذ قيل لهم اسكنوا هذه القرية﴾، وفي البقرة: ﴿وإذ قلنا ادخلوا هذه القرية﴾؟","answer":"الأعراف تركز على إقامتهم في القرية فقال ﴿اسكنوا﴾ وبُني القول للمجهول في سرد القصة؛ والبقرة في مقام تعداد النعم فصرح بالآمر وبدأ بنعمة الدخول.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1125","number":1125,"surah":7,"verses":[161],"verseLabel":"الأعراف: 161","question":"لماذا بُني ﴿قيل﴾ للمجهول هنا، وأُسند القول إلى الله في البقرة؟","answer":"بناء ﴿قيل﴾ للمجهول يوجز الحكاية لأن القائل معلوم، أما ﴿قلنا﴾ في البقرة فيبرز المنعم ضمن سياق الامتنان المباشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1126","number":1126,"surah":7,"verses":[161],"verseLabel":"الأعراف: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿اسكنوا﴾ هنا و﴿ادخلوا﴾ في البقرة؟","answer":"﴿ادخلوا﴾ يلحظ ابتداء الوصول إلى القرية، و﴿اسكنوا﴾ يلحظ الإقامة والاستقرار فيها؛ فكل لفظ يناسب زاوية السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1127","number":1127,"surah":7,"verses":[161],"verseLabel":"الأعراف: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿وكلوا منها حيث شئتم﴾، وفي البقرة: ﴿فكلوا منها حيث شئتم رغدًا﴾؟","answer":"البقرة زادت الفاء و﴿رغدًا﴾ في مقام توسيع النعمة وسرعة التمتع بعد الدخول، أما الأعراف فاقتصر على أصل الإباحة في سياق موجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1128","number":1128,"surah":7,"verses":[161],"verseLabel":"الأعراف: 161","question":"لماذا حُذفت ﴿رغدًا﴾ في الأعراف؟","answer":"حذفت لأن مقام الأعراف ليس مقام بسط الامتنان كما في البقرة، ولأن ﴿حيث شئتم﴾ يفيد سعة الانتفاع أصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1129","number":1129,"surah":7,"verses":[161],"verseLabel":"الأعراف: 161","question":"ما سرّ تقديم هنا ﴿قولوا حطة﴾ على ﴿وادخلوا الباب سجدًا﴾، وعُكس الترتيب في البقرة؟","answer":"في الأعراف قدم القول لأنه المقصود الأبرز في سياق تبديلهم القول، وفي البقرة قدم هيئة الدخول ضمن تعداد النعم والأوامر؛ فترتب كل سياق على محوره.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1130","number":1130,"surah":7,"verses":[161],"verseLabel":"الأعراف: 161","question":"ما دلالة الأمر بكلمة واحدة: ﴿حطة﴾؟","answer":"﴿حطة﴾ كلمة جامعة، أي مسألتنا حط خطايانا عنا؛ فاختصر بها الاعتراف وطلب المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1131","number":1131,"surah":7,"verses":[161],"verseLabel":"الأعراف: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿وادخلوا الباب سجدًا﴾، وكيف يكون الدخول سجودًا؟","answer":"أي ادخلوا خاضعين منحنين أو حال كونكم سجدًا عند الباب؛ فالسجود وصف لهيئتهم الدالة على التواضع، لا لعملية المشي نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1132","number":1132,"surah":7,"verses":[161],"verseLabel":"الأعراف: 161","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿نغفر لكم خطيئاتكم﴾، وفي البقرة: ﴿نغفر لكم خطاياكم﴾؟","answer":"﴿خطيئاتكم﴾ جمع قلة يلائم خطاب الغائبين في سياق موجز، و﴿خطاياكم﴾ من جموع الكثرة يلائم مقام الامتنان الأوسع في البقرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1133","number":1133,"surah":7,"verses":[161],"verseLabel":"الأعراف: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿سنزيد المحسنين﴾ من غير واو، وفي البقرة: ﴿وسنزيد المحسنين﴾؟","answer":"في الأعراف استؤنفت جملة ﴿سنزيد﴾ وعدًا مستقلًا، أما الواو في البقرة فعطفت الزيادة على المغفرة ضمن تعداد النعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1134","number":1134,"surah":7,"verses":[161],"verseLabel":"الأعراف: 161","question":"لماذا تجاوز الوعد المغفرة إلى الزيادة للمحسنين؟","answer":"المغفرة ترفع أثر الإساءة، ثم الزيادة تمنح المحسنين فضلًا فوق مجرد العفو؛ فجزاء الإحسان إحسان زائد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1135","number":1135,"surah":7,"verses":[162],"verseLabel":"الأعراف: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿فبدل الذين ظلموا منهم﴾، وزاد ﴿منهم﴾ خلاف موضع البقرة؟","answer":"﴿منهم﴾ للتبعيض؛ فهي تمنع تعميم الظلم على بني إسرائيل كلهم، وهو مناسب لما سبق من إثبات أمة تهدي بالحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1136","number":1136,"surah":7,"verses":[162],"verseLabel":"الأعراف: 162","question":"لماذا وُصف المبدّلون بـ﴿الذين ظلموا﴾؟","answer":"وصفهم بالظلم لأنهم وضعوا القول والفعل في غير موضعهما، فكان التبديل مظهرًا من ظلمهم لا مجرد خطأ لفظي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1137","number":1137,"surah":7,"verses":[162],"verseLabel":"الأعراف: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿قولًا غير الذي قيل لهم﴾ ولم يذكر القول الذي بدلوه به؟","answer":"أبهم القول البديل لأن العبرة بجريمة مخالفة الأمر لا بتخليد لفظ سخريتهم، ولأن الروايات في تعيينه متعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1138","number":1138,"surah":7,"verses":[162],"verseLabel":"الأعراف: 162","question":"لماذا كرر مادة القول: ﴿قولًا غير الذي قيل لهم﴾؟","answer":"الأول مفعول يبين أنهم استبدلوا قولًا، والثاني في الصلة يذكر القول المأمور به؛ فتقابل القولان وظهر التبديل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1139","number":1139,"surah":7,"verses":[162],"verseLabel":"الأعراف: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿فأرسلنا عليهم رجزًا﴾ لا «فأنزلنا»؟","answer":"الإرسال يدل على تسليط العذاب وتوجيهه إليهم بأمر الله، لا مجرد نزوله المكاني.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1140","number":1140,"surah":7,"verses":[162],"verseLabel":"الأعراف: 162","question":"لماذا عُدي الرجز بـ﴿عليهم﴾؟","answer":"﴿عليهم﴾ تصور الرجز نازلًا مستوليًا محيطًا بهم من فوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1141","number":1141,"surah":7,"verses":[162],"verseLabel":"الأعراف: 162","question":"لماذا قُيد الرجز بأنه ﴿من السماء﴾؟","answer":"لتأكيد أن العذاب جاء من جهة لا يملكون دفعها وبأمر إلهي، لا من سبب أرضي مألوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1142","number":1142,"surah":7,"verses":[162],"verseLabel":"الأعراف: 162","question":"لماذا ختم هنا بـ﴿بما كانوا يظلمون﴾، وفي البقرة: ﴿بما كانوا يفسقون﴾؟","answer":"الأعراف بنت القصة على ظلمهم في قوله ﴿فبدل الذين ظلموا منهم﴾ فختمت بالظلم، والبقرة أبرزت خروجهم عن الطاعة فختمت بالفسق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1143","number":1143,"surah":7,"verses":[162],"verseLabel":"الأعراف: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿كانوا يظلمون﴾ لا «ظلموا»؟","answer":"﴿كانوا يظلمون﴾ تفيد أن الظلم كان دأبًا متكررًا راسخًا، لا واقعة تبديل منفردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص751–779.","url":""}]},{"id":"s7-1144","number":1144,"surah":7,"verses":[163],"verseLabel":"الأعراف: 163","question":"ما سرّ التعبير في قوله تعالى: ﴿واسألهم عن القرية﴾ ولم يسمِّ القرية؟","answer":"أبهم اسمها لأن المقصود العبرة بحال أهلها لا تعيين موقعها، وقيل هي أيلة أو غيرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص780–800.","url":""}]},{"id":"s7-1145","number":1145,"surah":7,"verses":[163],"verseLabel":"الأعراف: 163","question":"لماذا أُمر النبي أن يسألهم مع أن الله سيقص الخبر؟","answer":"الأمر بالسؤال للتقرير والتوبيخ؛ ليسأل اليهود سؤال من يعرف تاريخهم، فتقوم عليهم الحجة من خبر تقره كتبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص780–800.","url":""}]},{"id":"s7-1146","number":1146,"surah":7,"verses":[163],"verseLabel":"الأعراف: 163","question":"لماذا وُصفت القرية بأنها ﴿كانت حاضرة البحر﴾؟","answer":"الوصف يبين سبب الفتنة: قربها من البحر جعل الصيد موردًا ظاهرًا، وكانت الحيتان تحضر عند الساحل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص780–800.","url":""}]},{"id":"s7-1147","number":1147,"surah":7,"verses":[163],"verseLabel":"الأعراف: 163","question":"ما سرّ التعبير في قوله تعالى: ﴿حاضرة البحر﴾ لا «على البحر»؟","answer":"﴿حاضرة البحر﴾ تصور القرية ملاصقة له حاضرة عنده، لا مجرد وقوعها على شاطئ بعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص780–800.","url":""}]},{"id":"s7-1148","number":1148,"surah":7,"verses":[163],"verseLabel":"الأعراف: 163","question":"ما سرّ التعبير في قوله تعالى: ﴿إذ يعدون في السبت﴾، وما دلالة العدوان «في» السبت؟","answer":"﴿في السبت﴾ يدل على وقوع العدوان داخل حرمة اليوم وأحكامه؛ فقد تجاوزوا النهي عن الصيد فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص780–800.","url":""}]},{"id":"s7-1149","number":1149,"surah":7,"verses":[163],"verseLabel":"الأعراف: 163","question":"لماذا كرر ﴿إذ﴾: ﴿إذ يعدون... إذ تأتيهم حيتانهم﴾؟","answer":"الأولى تحدد زمن عدوانهم، والثانية تفصل صورة الابتلاء الذي وقع في ذلك الزمن؛ فتكرار ﴿إذ﴾ ينقل إلى مشهد أدق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص780–800.","url":""}]},{"id":"s7-1150","number":1150,"surah":7,"verses":[163],"verseLabel":"الأعراف: 163","question":"لماذا أضيفت الحيتان إليهم: ﴿حيتانهم﴾؟","answer":"أضيفت إليهم لأنها حيتان ساحلهم ومورد معاشهم الذي تعلق به ابتلاؤهم، لا ملكًا شرعيًا قبل الصيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص780–800.","url":""}]},{"id":"s7-1151","number":1151,"surah":7,"verses":[163],"verseLabel":"الأعراف: 163","question":"ما سرّ التعبير بقوله تعالى: ﴿يوم سبتهم﴾ فأضيف السبت إليهم؟","answer":"إضافته إليهم لأنه اليوم الذي خصص لهم وفرض عليهم تعظيمه، فازدادت مسؤوليتهم عن انتهاكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص780–800.","url":""}]},{"id":"s7-1152","number":1152,"surah":7,"verses":[163],"verseLabel":"الأعراف: 163","question":"لماذا وصف مجيء الحيتان بـ﴿شرعًا﴾؟","answer":"﴿شرعًا﴾ أي ظاهرة مرتفعة قريبة على وجه الماء، كأنها شارعة رؤوسها، فاشتد الإغراء والابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص780–800.","url":""}]},{"id":"s7-1153","number":1153,"surah":7,"verses":[163],"verseLabel":"الأعراف: 163","question":"لماذا قابل ﴿يوم سبتهم﴾ بـ﴿ويوم لا يسبتون لا تأتيهم﴾؟","answer":"قابل يوم الحرمة الذي تكثر فيه الحيتان بسائر الأيام التي يقل حضورها، ليظهر قصد الابتلاء لا المصادفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص780–800.","url":""}]},{"id":"s7-1154","number":1154,"surah":7,"verses":[163],"verseLabel":"الأعراف: 163","question":"لماذا كرر النفي في ﴿لا يسبتون لا تأتيهم﴾؟","answer":"الأولى تنفي فعلهم السبت في غير يومه، والثانية جواب ذلك الزمن تنفي مجيء الحيتان؛ فلكل نفي متعلَّق مستقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص780–800.","url":""}]},{"id":"s7-1155","number":1155,"surah":7,"verses":[163],"verseLabel":"الأعراف: 163","question":"ما سرّ التعبير في قوله تعالى: ﴿كذلك نبلوهم﴾، وإلى ماذا تشير الكاف؟","answer":"الكاف تشير إلى هذا الابتلاء العجيب بإظهار الحيتان يوم المنع وحجبها يوم الحل؛ أي بمثل ذلك الاختبار نعاملهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص780–800.","url":""}]},{"id":"s7-1156","number":1156,"surah":7,"verses":[163],"verseLabel":"الأعراف: 163","question":"لماذا عبّر بالمضارع ﴿نبلوهم﴾ عن ابتلاء ماضٍ؟","answer":"المضارع يستحضر صورة الابتلاء المتكرر كل أسبوع، كأنه يجري أمام السامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص780–800.","url":""}]},{"id":"s7-1157","number":1157,"surah":7,"verses":[163],"verseLabel":"الأعراف: 163","question":"لماذا ختم بـ﴿بما كانوا يفسقون﴾؟","answer":"جعل الفسق المستمر سبب الابتلاء والعقوبة؛ لأن خروجهم المتكرر عن الطاعة هو الذي هيأهم للتحايل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص780–800.","url":""}]},{"id":"s7-1158","number":1158,"surah":7,"verses":[164],"verseLabel":"الأعراف: 164","question":"لماذا بدأت الآية بـ﴿وإذ قالت أمة منهم﴾ مع أن الجماعات لم تُذكر بعد؟","answer":"افتتحت بـ﴿وإذ﴾ لاستحضار موقف جديد، وظهرت ﴿أمة﴾ أولًا تمهيدًا لانقسام أهل القرية إلى معتدين وواعظين وساكتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1159","number":1159,"surah":7,"verses":[164],"verseLabel":"الأعراف: 164","question":"لماذا نُكرت ﴿أمة﴾؟","answer":"نُكرت لأنها طائفة غير محصورة العدد، ولتمييز موقفها لا اسمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1160","number":1160,"surah":7,"verses":[164],"verseLabel":"الأعراف: 164","question":"ما دلالة استفهامهم: ﴿لم تعظون قومًا﴾؟","answer":"الاستفهام إنكاري عند القائلين؛ يستبعدون فائدة وعظ قوم يظنون أن العقوبة واقعة بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1161","number":1161,"surah":7,"verses":[164],"verseLabel":"الأعراف: 164","question":"لماذا نُكّر ﴿قومًا﴾ مع أنهم معروفون؟","answer":"التنكير للتحقير في نظر المتكلمين أو لأن المقصود جماعة موصوفة بالإصرار، وإن كانت معروفة الهوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1162","number":1162,"surah":7,"verses":[164],"verseLabel":"الأعراف: 164","question":"ما دلالة جمعهم بين قولهم: ﴿الله مهلكهم أو معذبهم عذابًا شديدًا﴾؟","answer":"جمعوا بين الإهلاك الذي يستأصلهم والعذاب الشديد الذي يؤلمهم دون استئصال؛ لأنهم لم يدروا أي العقوبتين تقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1163","number":1163,"surah":7,"verses":[164],"verseLabel":"الأعراف: 164","question":"لماذا جاء ﴿مهلكهم﴾ و﴿معذبهم﴾ باسم الفاعل؟","answer":"اسم الفاعل يستحضر العقوبة كأمر متوقع ثابت الوقوع، لا احتمالًا بعيدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1164","number":1164,"surah":7,"verses":[164],"verseLabel":"الأعراف: 164","question":"ما سرّ قولهم: ﴿عذابًا شديدًا﴾ بعد ﴿معذبهم﴾؟","answer":"المصدر المؤكد ﴿عذابًا﴾ مع وصفه بالشدة يفخم نوع التعذيب بعد ذكر فاعله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1165","number":1165,"surah":7,"verses":[164],"verseLabel":"الأعراف: 164","question":"ما دلالة جواب الواعظين بكلمة ﴿معذرة﴾؟","answer":"أي نعظهم إقامةً لمعذرتنا عند ربكم وأداءً لواجب النهي، ولو لم نر أثرًا عاجلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1166","number":1166,"surah":7,"verses":[164],"verseLabel":"الأعراف: 164","question":"ما الفرق الدلالي بين قراءتي ﴿معذرةٌ﴾ بالرفع و﴿معذرةً﴾ بالنصب؟","answer":"بالرفع: خبر لمبتدأ محذوف، أي موعظتنا معذرة ثابتة؛ وبالنصب: نعظهم معذرةً، أي لأجل الاعتذار. والقراءتان تجمعان ثبوت المعذرة وكونها غاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1167","number":1167,"surah":7,"verses":[164],"verseLabel":"الأعراف: 164","question":"ما سرّ تعبيرهم: ﴿إلى ربكم﴾ لا «إلى ربنا»؟","answer":"خاطبوهم بـ﴿ربكم﴾ تذكيرًا بأنهم أيضًا مسؤولون أمام الرب عن ترك الإنكار، مع أن ربهم وربنا واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1168","number":1168,"surah":7,"verses":[164],"verseLabel":"الأعراف: 164","question":"لماذا عطفوا ﴿ولعلهم يتقون﴾ على ﴿معذرة إلى ربكم﴾؟","answer":"لم يحصروا الغاية في إعذار أنفسهم، بل أبقوا باب رجوع المعتدين مفتوحًا؛ فالوعظ واجب ورجاء التقوى قائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1169","number":1169,"surah":7,"verses":[164],"verseLabel":"الأعراف: 164","question":"كيف يُفهم رجاؤهم ﴿لعلهم يتقون﴾ مع قول الآخرين إن الله مهلكهم؟","answer":"لم يقطع الواعظون بإهلاكهم، بل رجوا أثر النصيحة؛ لأن القلوب بيد الله، وغاية الناصح البلاغ مع عدم اليأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1170","number":1170,"surah":7,"verses":[165],"verseLabel":"الأعراف: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما نسوا ما ذكروا به﴾، وهل كان نسيانًا حقيقيًا؟","answer":"النسيان هنا ترك متعمد وإعراض حتى صار المذكَّر به كأنه منسي، لا ذهاب المعلومة من الذاكرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1171","number":1171,"surah":7,"verses":[165],"verseLabel":"الأعراف: 165","question":"لماذا بُني ﴿ذُكّروا﴾ للمجهول؟","answer":"بني للمجهول لأن العناية بالموعظة التي أعرضوا عنها، لا باسم الواعظ، وقد عرف من السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1172","number":1172,"surah":7,"verses":[165],"verseLabel":"الأعراف: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿أنجينا الذين ينهون عن السوء﴾، فوصفهم بالمضارع؟","answer":"المضارع ﴿ينهون﴾ يبين أنهم داوموا على النهي عن السوء ولم تكن موعظتهم موقفًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1173","number":1173,"surah":7,"verses":[165],"verseLabel":"الأعراف: 165","question":"لماذا سمّى فعل المعتدين ﴿السوء﴾؟","answer":"سماه سوءًا لجمع قبائح العدوان والتحايل والمعصية في وصف يظهر شدة قبحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1174","number":1174,"surah":7,"verses":[165],"verseLabel":"الأعراف: 165","question":"لماذا نصت الآية على نجاة الناهين وعذاب الظالمين وسكتت عن الفرقة التي قالت: ﴿لم تعظون﴾؟","answer":"سكت النص عن مصيرها فوقع الخلاف: قيل نجت لأنها كرهت الفعل، وقيل لم تنج لتركها النهي. ولا يجوز الجزم بما سكت عنه القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1175","number":1175,"surah":7,"verses":[165],"verseLabel":"الأعراف: 165","question":"لماذا قابل ﴿أنجينا﴾ بـ﴿وأخذنا﴾؟","answer":"الإنجاء إبعاد أهل النهي عن العذاب، والأخذ استيلاء العقوبة على الظالمين؛ فتقابلت النجاة والإحاطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1176","number":1176,"surah":7,"verses":[165],"verseLabel":"الأعراف: 165","question":"لماذا أعيد وصف المعتدين بـ﴿الذين ظلموا﴾؟","answer":"أعاد الموصول لتسجيل سبب الأخذ عليهم وإبراز أن العدوان ظلم مستحق للعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1177","number":1177,"surah":7,"verses":[165],"verseLabel":"الأعراف: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿بعذاب بئيس﴾، وما معنى «بئيس»؟","answer":"﴿بئيس﴾ شديد موجع ذو بؤس، فجاء الوصف ملائمًا لأخذ لا يستطيعون دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1178","number":1178,"surah":7,"verses":[165],"verseLabel":"الأعراف: 165","question":"ما أثر القراءات المتعددة في لفظ ﴿بئيس﴾؟","answer":"القراءات مثل بَئيس وبِئْس وبَيْئس تتقارب في أصل معنى الشدة والبؤس، وتثري تصوير فظاعة العذاب من غير اختلاف في أصل الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1179","number":1179,"surah":7,"verses":[165],"verseLabel":"الأعراف: 165","question":"لماذا ختم بـ﴿بما كانوا يفسقون﴾ لا «بما اعتدوا»؟","answer":"الفسق أعم وأرسخ؛ هو خروجهم المستمر عن الطاعة الذي تولد منه عدوان السبت، ولذلك قال ﴿كانوا يفسقون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1180","number":1180,"surah":7,"verses":[166],"verseLabel":"الأعراف: 166","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما عتوا عما نهوا عنه﴾ لا «لما عصوا»؟","answer":"العتو تجاوز الحد باستكبار وصلابة، فهو أبلغ من مطلق العصيان، ويصور إصرارهم بعد النهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1181","number":1181,"surah":7,"verses":[166],"verseLabel":"الأعراف: 166","question":"لماذا عُدّي العتو بـ﴿عن﴾؟","answer":"﴿عن﴾ تفيد المجاوزة والانصراف؛ عتوا متجاوزين ما نُهوا عنه غير مكترثين به.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1182","number":1182,"surah":7,"verses":[166],"verseLabel":"الأعراف: 166","question":"لماذا بُني ﴿نهوا﴾ للمجهول؟","answer":"بني للمجهول لأن المقصود عتوهم عن النهي نفسه بعد قيامه عليهم، لا تعيين من باشره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1183","number":1183,"surah":7,"verses":[166],"verseLabel":"الأعراف: 166","question":"ما سرّ التعبير في قوله تعالى: ﴿كونوا قردة﴾ بفعل الكون؟","answer":"الأمر التكويني بـ﴿كونوا﴾ أنشأ تحولهم فورًا إلى الحال المذكورة، لا أنه تكليف يملكون رفضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1184","number":1184,"surah":7,"verses":[166],"verseLabel":"الأعراف: 166","question":"لماذا نُكرت ﴿قردة﴾؟","answer":"التنكير للتحقير والتهويل: صاروا قردة على هيئة منكرة مهينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1185","number":1185,"surah":7,"verses":[166],"verseLabel":"الأعراف: 166","question":"لماذا وُصفوا بـ﴿خاسئين﴾ بعد مسخهم قردة؟","answer":"﴿خاسئين﴾ أي مبعدين أذلاء صاغرين؛ فالمسخ لم يكن تغير صورة فقط، بل عقوبة مهينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1186","number":1186,"surah":7,"verses":[166],"verseLabel":"الأعراف: 166","question":"ما الفرق بين هذا السياق وقوله في البقرة: ﴿كونوا قردة خاسئين﴾؟","answer":"البقرة تذكر المسخ عقب بيان علم المخاطبين بالقصة ضمن تعداد النعم والنقم، والأعراف تفصّل مقدماته من الابتلاء والوعظ والعتو؛ أما عبارة الحكم فواحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص10–45.","url":""}]},{"id":"s7-1187","number":1187,"surah":7,"verses":[167],"verseLabel":"الأعراف: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذ تأذن ربك﴾ لا «وإذ أذن»؟","answer":"﴿تأذن﴾ بمعنى أعلم إعلامًا مؤكدًا أو عزم وقضى، وصيغة التفعل تشعر بإظهار الإعلان وتحققه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص46–57.","url":""}]},{"id":"s7-1188","number":1188,"surah":7,"verses":[167],"verseLabel":"الأعراف: 167","question":"لماذا أضيف الرب إلى النبي ﷺ: ﴿ربك﴾ في خبر بني إسرائيل؟","answer":"إضافة الرب إلى النبي ﷺ تسلية له وبيان أن مدبر تاريخ بني إسرائيل هو ربه الذي يتولى أمر رسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص46–57.","url":""}]},{"id":"s7-1189","number":1189,"surah":7,"verses":[167],"verseLabel":"الأعراف: 167","question":"لماذا أكد الوعيد باللام والنون: ﴿ليبعثن عليهم﴾؟","answer":"اللام ونون التوكيد الثقيلة تقرران حتمية استمرار هذا الوعيد وعدم تخلفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص46–57.","url":""}]},{"id":"s7-1190","number":1190,"surah":7,"verses":[167],"verseLabel":"الأعراف: 167","question":"لماذا اختير ﴿ليبعثن﴾ لا «ليسلطن»؟","answer":"البعث إرسال وإثارة متجددة؛ يفيد أن الله يقيم عليهم في أزمنة مختلفة من يسومهم العذاب، وهو أوسع من تسليط واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص46–57.","url":""}]},{"id":"s7-1191","number":1191,"surah":7,"verses":[167],"verseLabel":"الأعراف: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى يوم القيامة﴾؟","answer":"يفيد استمرار أثر الوعيد في تاريخهم إلى قيام الساعة، لا حادثة منقطعة في زمن واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص46–57.","url":""}]},{"id":"s7-1192","number":1192,"surah":7,"verses":[167],"verseLabel":"الأعراف: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿من يسومهم سوء العذاب﴾ ولم يذكر الفاعل؟","answer":"أبهم الفاعل ليعم كل من يبعثه الله عليهم في العصور المختلفة، فالعبرة بدوام سنة العقوبة لا باسم أمة بعينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص46–57.","url":""}]},{"id":"s7-1193","number":1193,"surah":7,"verses":[167],"verseLabel":"الأعراف: 167","question":"لماذا كرر التعبير ﴿يسومهم سوء العذاب﴾ من قصة فرعون؟","answer":"التكرار يربط جزاءهم اللاحق بما كان آل فرعون يفعلونه بهم؛ كأن من لم يعتبر بالنعمة عاد عليه جنس العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص46–57.","url":""}]},{"id":"s7-1194","number":1194,"surah":7,"verses":[167],"verseLabel":"الأعراف: 167","question":"لماذا ختم الوعيد بـ﴿إن ربك لسريع العقاب وإنه لغفور رحيم﴾؟","answer":"جمع بين سرعة العقاب لمن أصر، والمغفرة والرحمة لمن تاب، حتى لا يأمن العاصي ولا ييأس الراجع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص46–57.","url":""}]},{"id":"s7-1195","number":1195,"surah":7,"verses":[167],"verseLabel":"الأعراف: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿سريع العقاب﴾ مع امتداد العقوبة إلى القيامة؟","answer":"سرعته تعني أنه إذا جاء أجله لم يتأخر، وأن مقدماته متتابعة، وطول امتداده لا ينافي سرعة ابتدائه أو نفاذ حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص46–57.","url":""}]},{"id":"s7-1196","number":1196,"surah":7,"verses":[167],"verseLabel":"الأعراف: 167","question":"لماذا أظهر ﴿ربك﴾ أولًا ثم أضمر في ﴿وإنه﴾؟","answer":"أظهر ﴿ربك﴾ لإبراز وصف الربوبية وتثبيت النبي ﷺ، ثم عاد الضمير لاتضاح المرجع وتجنب التكرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص46–57.","url":""}]},{"id":"s7-1197","number":1197,"surah":7,"verses":[167],"verseLabel":"الأعراف: 167","question":"لماذا وصف بالمغفرة والرحمة بعد ذكر العقاب لا قبله؟","answer":"جاءت المغفرة والرحمة بعد الوعيد لتفتح باب التوبة عقب التخويف؛ فالخاتمة لا تلغي العقاب بل تبين طريق النجاة منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص46–57.","url":""}]},{"id":"s7-1198","number":1198,"surah":7,"verses":[168],"verseLabel":"الأعراف: 168","question":"ما سرّ التعبير في قوله تعالى: ﴿وقطعناهم في الأرض أممًا﴾، واستعار التقطيع للتفريق؟","answer":"صور تفريقهم في نواحي الأرض كتقطيع الشيء الواحد إلى قطع متباعدة، فدل على شدة التفرق بعد اجتماع الأصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص58–88.","url":""}]},{"id":"s7-1199","number":1199,"surah":7,"verses":[168],"verseLabel":"الأعراف: 168","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿في الأرض﴾، وفي الآية 160: ﴿اثنتي عشرة أسباطًا أممًا﴾؟","answer":"في الآية 160 كان التقسيم المنظم إلى اثنتي عشرة جماعة، أما هنا فالكلام على تفريقهم في أقطار الأرض أممًا شتى؛ فزاد قيد المكان لبيان الانتشار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص58–88.","url":""}]},{"id":"s7-1200","number":1200,"surah":7,"verses":[168],"verseLabel":"الأعراف: 168","question":"لماذا جُمعت ﴿أممًا﴾؟","answer":"جُمعت لاختلاف جماعاتهم ومواطنهم وأحوالهم بعد تفريقهم في الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص58–88.","url":""}]},{"id":"s7-1201","number":1201,"surah":7,"verses":[168],"verseLabel":"الأعراف: 168","question":"لماذا قدّم ﴿منهم الصالحون﴾ على ﴿ومنهم دون ذلك﴾؟","answer":"بدأ بالصالحين إنصافًا لهم وتنويهًا بشأنهم، حتى لا يعمم الذم على بني إسرائيل كلهم، ثم ذكر من انحط عن درجتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص58–88.","url":""}]},{"id":"s7-1202","number":1202,"surah":7,"verses":[168],"verseLabel":"الأعراف: 168","question":"ما سرّ التعبير في قوله تعالى: ﴿ومنهم دون ذلك﴾، دون أن يقال: ومنهم الفاسقون؟","answer":"﴿دون ذلك﴾ تشمل درجات متعددة أقل من الصلاح، وفيها عدل ودقة؛ فلم يحصر الجميع في وصف الفسق على تفاوت أحوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص58–88.","url":""}]},{"id":"s7-1203","number":1203,"surah":7,"verses":[168],"verseLabel":"الأعراف: 168","question":"لماذا استعمل اسم الإشارة ﴿ذلك﴾ في ﴿دون ذلك﴾؟","answer":"يشير إلى مقام الصلاح المذكور، أي ومنهم جماعات في مراتب أدنى منه؛ والإشارة تجعل الصلاح منزلة معلومة يقاس بها غيرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص58–88.","url":""}]},{"id":"s7-1204","number":1204,"surah":7,"verses":[168],"verseLabel":"الأعراف: 168","question":"ما سرّ التعبير في قوله تعالى: ﴿وبلوناهم بالحسنات والسيئات﴾؟","answer":"اختبرهم الله بالنعم والنقم معًا؛ فالحسنات تمتحن الشكر، والسيئات تمتحن الصبر وتدعو إلى التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص58–88.","url":""}]},{"id":"s7-1205","number":1205,"surah":7,"verses":[168],"verseLabel":"الأعراف: 168","question":"لماذا عُدّي البلاء بالباء في ﴿بالحسنات والسيئات﴾؟","answer":"الباء تفيد الملابسة أو السببية؛ أي جعل الحسنات والسيئات أدوات للابتلاء والاختبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص58–88.","url":""}]},{"id":"s7-1206","number":1206,"surah":7,"verses":[168],"verseLabel":"الأعراف: 168","question":"لماذا قدّم الحسنات على السيئات هنا، وقدمت الشدة في مواضع أخرى؟","answer":"قُدمت الحسنات لأنها الأصل في نعم الله والأسبق في تعداد حالهم هنا، ولأن النعمة اختبار كما أن الشدة اختبار؛ أما المواضع الأخرى فيحكمها سياق التخويف.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص58–88.","url":""}]},{"id":"s7-1207","number":1207,"surah":7,"verses":[168],"verseLabel":"الأعراف: 168","question":"لماذا خُتم بـ﴿لعلهم يرجعون﴾؟","answer":"جعل غاية تنويع الابتلاء رجوعهم عن العصيان إلى الطاعة، فليس المقصود مجرد العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص58–88.","url":""}]},{"id":"s7-1208","number":1208,"surah":7,"verses":[168],"verseLabel":"الأعراف: 168","question":"ما سرّ التعبير في قوله تعالى: ﴿يرجعون﴾ لا «يتقون» أو «يذكرون»؟","answer":"الرجوع يصور أنهم كانوا على طريق الحق ثم انصرفوا عنه، والمطلوب عودتهم إليه؛ وهو أنسب بتاريخ قوم عرفوا الكتاب ثم خالفوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص58–88.","url":""}]},{"id":"s7-1209","number":1209,"surah":7,"verses":[169],"verseLabel":"الأعراف: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿فخلف من بعدهم خلف﴾، وما الفرق في دلالة «الخَلْف»؟","answer":"﴿الخَلْف﴾ بسكون اللام يكثر في الخلف السيئ، بخلاف الخَلَف الصالح؛ فاختيار اللفظ يشعر بسوء من جاء بعد الصالحين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص89–96.","url":""}]},{"id":"s7-1210","number":1210,"surah":7,"verses":[169],"verseLabel":"الأعراف: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعدهم﴾ مع أن الخلافة تقتضي التأخر؟","answer":"زاد ﴿من بعدهم﴾ لتأكيد المفارقة بين السلف الصالح والخلف السيئ، وبيان سرعة تتابع الانحراف بعدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص89–96.","url":""}]},{"id":"s7-1211","number":1211,"surah":7,"verses":[169],"verseLabel":"الأعراف: 169","question":"لماذا وصفهم بأنهم ﴿ورثوا الكتاب﴾ لا «أوتوا الكتاب»؟","answer":"الإرث وصول الكتاب إليهم عن أسلافهم بلا كسب منهم، وفيه تعريض بأنهم حملوا الاسم والنص ولم يحملوا حقه كما ينبغي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص89–96.","url":""}]},{"id":"s7-1212","number":1212,"surah":7,"verses":[169],"verseLabel":"الأعراف: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿يأخذون عرض هذا الأدنى﴾، دون أن يقال: متاع الدنيا؟","answer":"العَرَض متاع زائل يعرض ثم يذهب، و﴿هذا الأدنى﴾ تحقير للدنيا القريبة؛ فالتعبير يفضح استبدال الباقي بالعاجل الزهيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص89–96.","url":""}]},{"id":"s7-1213","number":1213,"surah":7,"verses":[169],"verseLabel":"الأعراف: 169","question":"لماذا سمى الدنيا ﴿هذا الأدنى﴾؟","answer":"الإشارة تحضر متاع الدنيا القريب، و﴿الأدنى﴾ تجمع معنى الأقرب والأحقر في مقابل الدار الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص89–96.","url":""}]},{"id":"s7-1214","number":1214,"surah":7,"verses":[169],"verseLabel":"الأعراف: 169","question":"ما دلالة قولهم: ﴿سيغفر لنا﴾ مع حذف اسم الله والاكتفاء بضمير الفاعل المستتر؟","answer":"فاعل ﴿سيغفر﴾ ضمير مستتر يعود إلى الله، وحذف اسمه من العبارة يكشف جرأتهم في ادعاء المغفرة لأنفسهم من غير توبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص89–96.","url":""}]},{"id":"s7-1215","number":1215,"surah":7,"verses":[169],"verseLabel":"الأعراف: 169","question":"لماذا عبروا بالسين: ﴿سيغفر لنا﴾؟","answer":"السين تصور المغفرة عندهم أمرًا قريبًا مضمونًا في المستقبل، فجمعوا بين المعصية والأمن من العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص89–96.","url":""}]},{"id":"s7-1216","number":1216,"surah":7,"verses":[169],"verseLabel":"الأعراف: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن يأتهم عرض مثله يأخذوه﴾؟","answer":"يكشف تكرر الجشع: كلما جاءهم متاع حرام مماثل أخذوه، مع استمرارهم في دعوى المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص89–96.","url":""}]},{"id":"s7-1217","number":1217,"surah":7,"verses":[169],"verseLabel":"الأعراف: 169","question":"لماذا كرر مادة الأخذ والعرض؟","answer":"تكرار اللفظين يجسد تكرر السلوك نفسه؛ يأخذون العرض أولًا ثم يعاودون أخذه متى تجدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص89–96.","url":""}]},{"id":"s7-1218","number":1218,"surah":7,"verses":[169],"verseLabel":"الأعراف: 169","question":"لماذا وبخهم باستفهام: ﴿ألم يؤخذ عليهم ميثاق الكتاب﴾؟","answer":"الاستفهام تقريري توبيخي؛ يثبت أن الميثاق أُخذ عليهم بالفعل، فلا عذر لهم في القول على الله بغير الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص89–96.","url":""}]},{"id":"s7-1219","number":1219,"surah":7,"verses":[169],"verseLabel":"الأعراف: 169","question":"لماذا أضيف الميثاق إلى الكتاب؟","answer":"لأن مضمون الميثاق ثابت في الكتاب الذي ورثوه ودرسوه؛ فهو عهد مرتبط بحفظ أحكامه وعدم تحريفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص89–96.","url":""}]},{"id":"s7-1220","number":1220,"surah":7,"verses":[169],"verseLabel":"الأعراف: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿أن لا يقولوا على الله إلا الحق﴾؟","answer":"هذا تفسير للميثاق: ألا ينسبوا إلى الله إلا ما ثبت حقًا، وفيه تعريض بأن دعوى ﴿سيغفر لنا﴾ قول بلا حجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص89–96.","url":""}]},{"id":"s7-1221","number":1221,"surah":7,"verses":[169],"verseLabel":"الأعراف: 169","question":"لماذا عقب بقوله: ﴿ودرسوا ما فيه﴾؟","answer":"ذكّر بأنهم قرؤوا ما في الكتاب وعرفوه، فمخالفتهم ليست عن جهل بل بعد درس وعلم، وهو أبلغ في إقامة الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص89–96.","url":""}]},{"id":"s7-1222","number":1222,"surah":7,"verses":[169],"verseLabel":"الأعراف: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿والدار الآخرة خير للذين يتقون﴾؟","answer":"متاع الآخرة أبقى وأعظم من العرض الأدنى الذي يأخذونه، فالمقابلة ترد ميزانهم من العاجل الزائل إلى الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص89–96.","url":""}]},{"id":"s7-1223","number":1223,"surah":7,"verses":[169],"verseLabel":"الأعراف: 169","question":"لماذا قيد خيرية الآخرة بـ﴿للذين يتقون﴾؟","answer":"لأن خير الآخرة لا يناله من آثر الحرام واغتر بالمغفرة، وإنما ينتفع به من اتقى الله ووفى بميثاق الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص89–96.","url":""}]},{"id":"s7-1224","number":1224,"surah":7,"verses":[169],"verseLabel":"الأعراف: 169","question":"لماذا ختم بـ﴿أفلا تعقلون﴾، وفي قراءة ﴿يعقلون﴾؟","answer":"الاستفهام يحض على إدراك التفاوت الواضح بين عرض الدنيا والآخرة. وفي قراءة الخطاب مواجهة لهم، وفي الغيبة حكاية لحالهم وتعجيب السامعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص89–96.","url":""}]},{"id":"s7-1225","number":1225,"surah":7,"verses":[170],"verseLabel":"الأعراف: 170","question":"ما سرّ التعبير في قوله تعالى: ﴿والذين يمسكون بالكتاب﴾ بصيغة التشديد؟","answer":"التشديد في ﴿يُمَسِّكون﴾ يفيد شدة الاستمساك وتكرره، كأنهم يجدّدون القبض على الكتاب ولا يتركون شيئًا منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص97–111.","url":""}]},{"id":"s7-1226","number":1226,"surah":7,"verses":[170],"verseLabel":"الأعراف: 170","question":"ما سرّ التعبير في قوله تعالى: ﴿يمسكون بالكتاب﴾ لا «يقرؤون الكتاب»؟","answer":"التمسك هو الأخذ الجاد بما في الكتاب علمًا وعملًا، لا مجرد تلاوته بلا امتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص97–111.","url":""}]},{"id":"s7-1227","number":1227,"surah":7,"verses":[170],"verseLabel":"الأعراف: 170","question":"لماذا عطف ﴿وأقاموا الصلاة﴾ بالماضي على المضارع ﴿يمسكون﴾؟","answer":"المضارع يستحضر دوام تمسكهم، والماضي في ﴿أقاموا﴾ يقرر تحقق إقامة الصلاة وثباتها منهم؛ فجمع الاستمرار والتحقق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص97–111.","url":""}]},{"id":"s7-1228","number":1228,"surah":7,"verses":[170],"verseLabel":"الأعراف: 170","question":"لماذا خُصت الصلاة بعد التمسك بالكتاب؟","answer":"خُصت لأنها عماد العمل وأظهر ما يدل على صدق التمسك بالكتاب، وتجمع صلة العبد بربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص97–111.","url":""}]},{"id":"s7-1229","number":1229,"surah":7,"verses":[170],"verseLabel":"الأعراف: 170","question":"لماذا عدل من ضمير الغيبة إلى التعظيم: ﴿إنا لا نضيع﴾؟","answer":"الالتفات إلى ﴿إنا لا نضيع﴾ يؤكد الوعد مباشرة بضمير العظمة ويطمئن العاملين إلى حفظ أجرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص97–111.","url":""}]},{"id":"s7-1230","number":1230,"surah":7,"verses":[170],"verseLabel":"الأعراف: 170","question":"ما سرّ التعبير في قوله تعالى: ﴿لا نضيع أجر المصلحين﴾، دون أن يقال: أجرهم؟","answer":"أظهر وصف ﴿المصلحين﴾ بدل الضمير ليبين علة حفظ الأجر، ويعم الوعد كل من تحقق بالإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص97–111.","url":""}]},{"id":"s7-1231","number":1231,"surah":7,"verses":[170],"verseLabel":"الأعراف: 170","question":"لماذا وصفهم بـ﴿المصلحين﴾ لا «الصالحين»؟","answer":"المصلح يتعدى صلاحه إلى إقامة الكتاب والصلاة وإصلاح غيره، وهو أبلغ من الصالح الذي قد يقتصر خيره على نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص97–111.","url":""}]},{"id":"s7-1232","number":1232,"surah":7,"verses":[170],"verseLabel":"الأعراف: 170؛ قراءة التخفيف والتشديد","question":"ما الفرق بين قراءتي ﴿يُمْسِكون بالكتاب﴾ و﴿يُمَسِّكون بالكتاب﴾، وما الذي تضيفه صيغة التشديد؟","answer":"قراءة التخفيف من «أمسك» تدل على التعلق بالكتاب وعدم تركه، وقراءة التشديد من «مسّك» تزيد معنى التكلف والمبالغة وتكرار الاستمساك؛ وكلتاهما تقتضي العمل بما فيه.","sources":[{"label":"الطبري، جامع البيان، ج13، ص217، عند الأعراف: 170؛ وموسوعة التفسير البلاغي، ج15، ص97–111.","url":""}]},{"id":"s7-1233","number":1233,"surah":7,"verses":[171],"verseLabel":"الأعراف: 171","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذ نتقنا الجبل﴾، وما دلالة «نتقنا»؟","answer":"النتق اقتلاع الشيء من أصله ورفعه بقوة، فصوّر رفع الجبل بعد اقتلاعه فوقهم تصويرًا مهيبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص112–128.","url":""}]},{"id":"s7-1234","number":1234,"surah":7,"verses":[171],"verseLabel":"الأعراف: 171","question":"ما سرّ التعبير في قوله تعالى: ﴿فوقهم﴾؟","answer":"يبين أنه صار معلقًا في جهة العلو مباشرة فوق رؤوسهم، فكان التهديد حاضرًا لا بعيدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص112–128.","url":""}]},{"id":"s7-1235","number":1235,"surah":7,"verses":[171],"verseLabel":"الأعراف: 171","question":"لماذا شُبّه الجبل بـ﴿ظلة﴾ مع أنه أعظم منها؟","answer":"التشبيه من جهة كونه ساترًا معلقًا فوقهم كالسحابة المظلة، لا من جهة الحجم؛ فهو يصف هيئته بالنسبة إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص112–128.","url":""}]},{"id":"s7-1236","number":1236,"surah":7,"verses":[171],"verseLabel":"الأعراف: 171","question":"لماذا نُكرت ﴿ظلة﴾؟","answer":"التنكير للتهويل: صار فوقهم ظلة عظيمة مخيفة لا ظلة رحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص112–128.","url":""}]},{"id":"s7-1237","number":1237,"surah":7,"verses":[171],"verseLabel":"الأعراف: 171","question":"ما سرّ التعبير في قوله تعالى: ﴿وظنوا أنه واقع بهم﴾ مع رؤيتهم الجبل فوقهم؟","answer":"الظن هنا بمعنى اليقين أو غلبة اليقين؛ فقد شاهدوا أمارات سقوطه حتى أيقنوا أنه واقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص112–128.","url":""}]},{"id":"s7-1238","number":1238,"surah":7,"verses":[171],"verseLabel":"الأعراف: 171","question":"ما سرّ التعبير في قوله تعالى: ﴿واقع بهم﴾ لا «واقع عليهم»؟","answer":"الباء تفيد الإلصاق والوقوع المتلبس بهم، فتشعر بأنه سيصيبهم ويحيط بهم، لا مجرد سقوط في جهة فوقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص112–128.","url":""}]},{"id":"s7-1239","number":1239,"surah":7,"verses":[171],"verseLabel":"الأعراف: 171","question":"لماذا حُذف فعل القول قبل ﴿خذوا ما آتيناكم بقوة﴾؟","answer":"حذف القول للإيجاز وسرعة الانتقال من مشهد التهديد إلى الأمر المقصود؛ والتقدير: وقلنا خذوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص112–128.","url":""}]},{"id":"s7-1240","number":1240,"surah":7,"verses":[171],"verseLabel":"الأعراف: 171","question":"لماذا تكرر الأمر بالأخذ بقوة بعد الآية 145؟","answer":"تكرر لأن الأمر هنا جُدد لجماعة بني إسرائيل عند رفع الجبل وأخذ الميثاق، أما الآية 145 فكان خطابًا لموسى عند تسليم الألواح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص112–128.","url":""}]},{"id":"s7-1241","number":1241,"surah":7,"verses":[171],"verseLabel":"الأعراف: 171","question":"ما سرّ التعبير في قوله تعالى: ﴿واذكروا ما فيه﴾ بعد ﴿خذوا﴾؟","answer":"الأخذ بالقوة التزام ظاهر، والذكر حفظ للمضمون وتدبر وعمل دائم؛ فلا يكفي حمل الكتاب من غير وعي ما فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص112–128.","url":""}]},{"id":"s7-1242","number":1242,"surah":7,"verses":[171],"verseLabel":"الأعراف: 171","question":"لماذا ختم بـ﴿لعلكم تتقون﴾؟","answer":"غاية الأخذ الجاد والذكر أن تنشأ التقوى، فيحجزهم الكتاب عن المخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص112–128.","url":""}]},{"id":"s7-1243","number":1243,"surah":7,"verses":[171],"verseLabel":"الأعراف: 171","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿وإذ نتقنا الجبل فوقهم﴾، وفي البقرة: ﴿ورفعنا فوقكم الطور﴾؟","answer":"﴿نتقنا﴾ في الأعراف يلائم تفصيل مشهد التهديد واقتلاع الجبل، أما ﴿رفعنا﴾ في البقرة فيوجز الحدث ضمن تعداد النعم والمواثيق.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص545–548.","url":""}]},{"id":"s7-1244","number":1244,"surah":7,"verses":[171],"verseLabel":"الأعراف: 171","question":"لماذا اختير لفظ ﴿نتقنا﴾ في السورة المكية، واختير ﴿رفعنا﴾ في خطاب بني إسرائيل في البقرة؟","answer":"السورة المكية تعرض القصة للتخويف والعبرة فاختارت اللفظ الأقوى في التصوير، والبقرة تخاطب بني إسرائيل بتذكير موجز بالفعل المعروف ﴿رفعنا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص545–548.","url":""}]},{"id":"s7-1245","number":1245,"surah":7,"verses":[172],"verseLabel":"الأعراف: 172","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذ أخذ ربك من بني آدم﴾، دون أن يقال: من آدم؟","answer":"ذكر بني آدم يجعل الأخذ متكررًا في نسل الإنسان جيلاً بعد جيل، لا حدثًا مقصورًا على آدم وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص129–137.","url":""}]},{"id":"s7-1246","number":1246,"surah":7,"verses":[172],"verseLabel":"الأعراف: 172","question":"لماذا أضيف الرب إلى النبي ﷺ: ﴿ربك﴾؟","answer":"إضافة الرب إلى النبي ﷺ تستحضر عنايته وتربيته وهو يقص عليه أصل الحجة على البشر، وتثبت أن آخذ الميثاق هو ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص129–137.","url":""}]},{"id":"s7-1247","number":1247,"surah":7,"verses":[172],"verseLabel":"الأعراف: 172","question":"ما سرّ التعبير في قوله تعالى: ﴿من ظهورهم ذريتهم﴾ فكرر معنى النسل؟","answer":"﴿من ظهورهم﴾ يبين موضع خروج النسل من الآباء، و﴿ذريتهم﴾ يبين المأخوذ؛ فليس تكرارًا بل تفصيل للمصدر والمستخرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص129–137.","url":""}]},{"id":"s7-1248","number":1248,"surah":7,"verses":[172],"verseLabel":"الأعراف: 172","question":"لماذا جمع ﴿ظهورهم﴾ وأفرد جنس ﴿ذريتهم﴾؟","answer":"جُمعت الظهور لتعدد الآباء، وجاءت الذرية اسم جنس أو جمعًا يدل على مجموع النسل الخارج منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص129–137.","url":""}]},{"id":"s7-1249","number":1249,"surah":7,"verses":[172],"verseLabel":"الأعراف: 172","question":"ما سرّ التعبير في قوله تعالى: ﴿وأشهدهم على أنفسهم﴾؟","answer":"جعلهم شاهدين على حقيقة مستقرة في فطرهم، فلا يستطيع المرء أن يدفع إقرار نفسه بربوبية خالقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص129–137.","url":""}]},{"id":"s7-1250","number":1250,"surah":7,"verses":[172],"verseLabel":"الأعراف: 172","question":"لماذا جاء التقرير باستفهام: ﴿ألست بربكم﴾؟","answer":"الاستفهام تقريري يلزمهم بالإجابة التي لا يسع الفطرة إنكارها، فيتحول العلم بالربوبية إلى شهادة صريحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص129–137.","url":""}]},{"id":"s7-1251","number":1251,"surah":7,"verses":[172],"verseLabel":"الأعراف: 172","question":"لماذا زيدت الباء في ﴿بربكم﴾؟","answer":"الباء زائدة للتوكيد في خبر ﴿ليس﴾، فتقوي تقرير الربوبية ونفي أي احتمال لإنكارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص129–137.","url":""}]},{"id":"s7-1252","number":1252,"surah":7,"verses":[172],"verseLabel":"الأعراف: 172","question":"ما دلالة جوابهم: ﴿بلى شهدنا﴾ وجمعه بين الإقرار والشهادة؟","answer":"﴿بلى﴾ تبطل النفي وتثبت الربوبية، و﴿شهدنا﴾ يوثق الإقرار ويحمّلهم تبعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص129–137.","url":""}]},{"id":"s7-1253","number":1253,"surah":7,"verses":[172],"verseLabel":"الأعراف: 172","question":"لماذا حُذف متعلق ﴿شهدنا﴾ أو المشهود به؟","answer":"حذف لدلالة السؤال عليه؛ أي شهدنا أنك ربنا، فالإيجاز يثبت الجواب من غير إعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص129–137.","url":""}]},{"id":"s7-1254","number":1254,"surah":7,"verses":[172],"verseLabel":"الأعراف: 172","question":"ما سرّ التعبير في قوله تعالى: ﴿أن تقولوا يوم القيامة إنا كنا عن هذا غافلين﴾؟","answer":"بيّن غاية الإشهاد: قطع عذر الغفلة يوم القيامة، فلا يقولوا إن أصل معرفة الرب لم يقم في فطرتهم ولم تبلغهم دلائله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص129–137.","url":""}]},{"id":"s7-1255","number":1255,"surah":7,"verses":[172],"verseLabel":"الأعراف: 172","question":"إلى ماذا يشير ﴿هذا﴾؟","answer":"يشير إلى التوحيد والإقرار بربوبية الله، أو إلى الميثاق والإشهاد المذكور.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص129–137.","url":""}]},{"id":"s7-1256","number":1256,"surah":7,"verses":[172],"verseLabel":"الأعراف: 172","question":"ما سرّ التعبير في قوله تعالى في ميثاق ذرية آدم: ﴿وإذ أخذ ربك﴾، بينما يقال في مواثيق أخرى: ﴿أخذ الله﴾ و﴿أخذنا﴾؟","answer":"﴿ربك﴾ تلائم مقام التربية والعناية بخاتم الرسل الذي يبلّغ الناس الميثاق، و﴿أخذ الله﴾ يبرز الاسم الجامع في مواثيق، و﴿أخذنا﴾ يبرز العظمة؛ فكل تعبير بحسب سياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص367.","url":""}]},{"id":"s7-1257","number":1257,"surah":7,"verses":[173],"verseLabel":"الأعراف: 173","question":"لماذا عطف العذر الثاني بـ﴿أو تقولوا﴾؟","answer":"العطف يعرض عذرًا آخر مغايرًا للأول: بعد دعوى الغفلة تأتي دعوى تقليد الآباء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص138–143.","url":""}]},{"id":"s7-1258","number":1258,"surah":7,"verses":[173],"verseLabel":"الأعراف: 173","question":"لماذا جاء القصر: ﴿إنما أشرك آباؤنا من قبل﴾؟","answer":"القصر يجعلون أصل الشرك محصورًا في الآباء السابقين، محاولين نفي المسؤولية عن أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص138–143.","url":""}]},{"id":"s7-1259","number":1259,"surah":7,"verses":[173],"verseLabel":"الأعراف: 173","question":"ما دلالة قولهم: ﴿من قبل﴾ مع وضوح سبق الآباء؟","answer":"زادوه لتأكيد سبق الآباء وبعد العهد، وبناء حجتهم على أنهم لم يكونوا مبتدئي الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص138–143.","url":""}]},{"id":"s7-1260","number":1260,"surah":7,"verses":[173],"verseLabel":"الأعراف: 173","question":"لماذا وصفوا أنفسهم بـ﴿ذرية من بعدهم﴾؟","answer":"صوروا أنفسهم نسلًا تابعًا جاء بعد الآباء، ليجعلوا التقليد قدَرًا ورثوه لا اختيارًا يحاسبون عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص138–143.","url":""}]},{"id":"s7-1261","number":1261,"surah":7,"verses":[173],"verseLabel":"الأعراف: 173","question":"لماذا سألوا: ﴿أفتهلكنا بما فعل المبطلون﴾؟","answer":"الاستفهام استعطاف احتجاجي بلسانهم: أتؤاخذنا بفعل من أبطل قبلنا؟ وقد قطع الميثاق هذا العذر لأن كل نفس مسؤولة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص138–143.","url":""}]},{"id":"s7-1262","number":1262,"surah":7,"verses":[173],"verseLabel":"الأعراف: 173","question":"لماذا سمى الآباء ﴿المبطلون﴾ لا «المشركون»؟","answer":"المبطل من يأتي بالباطل ويقيم عليه، وهو أوسع من الشرك فيشمل اختلاق العقائد والحجج الفاسدة التي ورثوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص138–143.","url":""}]},{"id":"s7-1263","number":1263,"surah":7,"verses":[174],"verseLabel":"الأعراف: 174","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذلك نفصل الآيات﴾؟","answer":"أي مثل هذا التفصيل الواضح لحجة الفطرة وأعذار البشر نفصل سائر الآيات؛ فالكاف تشير إلى البيان السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص138–143.","url":""}]},{"id":"s7-1264","number":1264,"surah":7,"verses":[174],"verseLabel":"الأعراف: 174","question":"لماذا عبّر بالمضارع ﴿نفصل﴾؟","answer":"المضارع يفيد تجدد تفصيل الآيات واستمراره بتنوع الأدلة والمواقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص138–143.","url":""}]},{"id":"s7-1265","number":1265,"surah":7,"verses":[174],"verseLabel":"الأعراف: 174","question":"لماذا جمع ﴿الآيات﴾؟","answer":"الجمع لتعدد الدلائل المبينة للتوحيد والمسؤولية وبطلان الأعذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص138–143.","url":""}]},{"id":"s7-1266","number":1266,"surah":7,"verses":[174],"verseLabel":"الأعراف: 174","question":"ما سرّ التعبير في قوله تعالى: ﴿ولعلهم يرجعون﴾ لا «لعلهم يؤمنون»؟","answer":"الرجوع أنسب لأن معرفة الرب مركوزة في الفطرة؛ فالمطلوب عودتهم إلى أصل أقروا به، لا إيمان مبتدأ لا سابقة له.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص138–143.","url":""}]},{"id":"s7-1267","number":1267,"surah":7,"verses":[174],"verseLabel":"الأعراف: 174","question":"لماذا عطف غاية الرجوع بالواو؟","answer":"الواو تجمع غايتين للتفصيل: إقامة الحجة وفتح طريق الرجوع، أو تعطف الرجاء على محذوف مفهوم كالتدبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص138–143.","url":""}]},{"id":"s7-1268","number":1268,"surah":7,"verses":[175],"verseLabel":"الأعراف: 175","question":"لماذا أمر النبي ﷺ: ﴿واتل عليهم نبأ الذي آتيناه آياتنا﴾؟","answer":"أمره أن يتلو القصة للعبرة والتحذير من عالم عرف الآيات ثم تركها؛ فهي مثال حي لمن لا ينتفع بالعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص144–156.","url":""}]},{"id":"s7-1269","number":1269,"surah":7,"verses":[175],"verseLabel":"الأعراف: 175","question":"ما سرّ التعبير في قوله تعالى: ﴿نبأ﴾ لا «خبر»؟","answer":"النبأ خبر عظيم ذو شأن وفائدة، وهذه القصة خطيرة العاقبة تتجاوز الخبر العادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص144–156.","url":""}]},{"id":"s7-1270","number":1270,"surah":7,"verses":[175],"verseLabel":"الأعراف: 175","question":"لماذا لم يسمِّ الرجل فقال: ﴿الذي آتيناه آياتنا﴾؟","answer":"أبهم اسمه لتعم العبرة كل من اتصف بحاله، ولأن المقصود فعله لا شخصه؛ والروايات في تعيينه مختلفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص144–156.","url":""}]},{"id":"s7-1271","number":1271,"surah":7,"verses":[175],"verseLabel":"الأعراف: 175","question":"ما سرّ التعبير في قوله تعالى: ﴿آتيناه آياتنا﴾ لا «علمناه»؟","answer":"الإيتاء تمليك وتمكين من الآيات والحجج، وهو أبلغ من مجرد تعليمه معلومة؛ فقد صارت في حوزته ثم نبذها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص144–156.","url":""}]},{"id":"s7-1272","number":1272,"surah":7,"verses":[175],"verseLabel":"الأعراف: 175","question":"لماذا أضاف الآيات إلى الله؟","answer":"لتشريفها وتعظيم جرم الانسلاخ منها؛ فهي آيات الله لا معارف بشرية عادية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص144–156.","url":""}]},{"id":"s7-1273","number":1273,"surah":7,"verses":[175],"verseLabel":"الأعراف: 175","question":"ما سرّ التعبير في قوله تعالى: ﴿فانسلخ منها﴾، وصوّر ترك الآيات بانسلاخ الجلد؟","answer":"الانسلاخ خروج الشيء من جلده الملتصق به؛ فصوّر الآيات كأنها كانت محيطة به ثم نزع نفسه منها نزعًا كاملًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص144–156.","url":""}]},{"id":"s7-1274","number":1274,"surah":7,"verses":[175],"verseLabel":"الأعراف: 175","question":"لماذا عُدّي الانسلاخ بـ﴿منها﴾؟","answer":"﴿منها﴾ تبين أنه خرج من داخل محيط الآيات الذي كان متلبسًا به، فاشتد معنى المفارقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص144–156.","url":""}]},{"id":"s7-1275","number":1275,"surah":7,"verses":[175],"verseLabel":"الأعراف: 175","question":"لماذا عطف ﴿فأتبعه الشيطان فكان من الغاوين﴾ بفاءين؟","answer":"الفاء الأولى تبين أن ملاحقة الشيطان ترتبت سريعًا على انسلاخه، والثانية أن دخوله في الغاوين كان نتيجة تلك الملاحقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص144–156.","url":""}]},{"id":"s7-1276","number":1276,"surah":7,"verses":[175],"verseLabel":"الأعراف: 175","question":"ما سرّ التعبير في قوله تعالى: ﴿فأتبعه الشيطان﴾ لا «فتبعه الشيطان»؟","answer":"﴿أتبعه﴾ بمعنى لحقه وأدركه بعد طلب، فيصور الشيطان مطاردًا له حتى استحوذ عليه؛ وهو أقوى من مجرد المصاحبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص144–156.","url":""}]},{"id":"s7-1277","number":1277,"surah":7,"verses":[175],"verseLabel":"الأعراف: 175","question":"لماذا أظهر ﴿الشيطان﴾ ولم يضمر سبب الغواية؟","answer":"أظهر الاسم لتسجيل دور العدو المعروف والتنبيه إلى أن الفراغ بعد ترك الآيات يملؤه الشيطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص144–156.","url":""}]},{"id":"s7-1278","number":1278,"surah":7,"verses":[175],"verseLabel":"الأعراف: 175","question":"ما سرّ التعبير في قوله تعالى: ﴿فكان من الغاوين﴾ لا «فغوى»؟","answer":"﴿كان من الغاوين﴾ تدخله في زمرة استقر فيها الغي وصار وصفًا لها، وهو أبلغ من وقوع غي عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص144–156.","url":""}]},{"id":"s7-1279","number":1279,"surah":7,"verses":[176],"verseLabel":"الأعراف: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿ولو شئنا لرفعناه بها﴾، وعلّق الرفع بالمشيئة؟","answer":"يبين أن رفعه بالآيات ممكن في قدرة الله، لكن المشيئة الحكيمة لم تتعلق بإكراه من اختار الهبوط واتباع الهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص157–171.","url":""}]},{"id":"s7-1280","number":1280,"surah":7,"verses":[176],"verseLabel":"الأعراف: 176","question":"لماذا عُدّي الرفع بالباء: ﴿بها﴾؟","answer":"الباء سببية أو استعانة؛ أي لرفعناه بسبب الآيات وبالعمل بها، فهي وسيلة الرفعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص157–171.","url":""}]},{"id":"s7-1281","number":1281,"surah":7,"verses":[176],"verseLabel":"الأعراف: 176","question":"لماذا لم يرفعه الله بالآيات مع أنه آتاه إياها؟","answer":"لأنه اختار الإخلاد إلى الأرض واتباع الهوى؛ والآيات لا ترفع من ينخلع منها ويعطل مقتضاها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص157–171.","url":""}]},{"id":"s7-1282","number":1282,"surah":7,"verses":[176],"verseLabel":"الأعراف: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكنه أخلد إلى الأرض﴾؟","answer":"الإخلاد شدة الميل مع الركون والدوام، والأرض كناية عن الدنيا وشهواتها؛ فصوّر نفسه ملتصقة بالسفول.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص157–171.","url":""}]},{"id":"s7-1283","number":1283,"surah":7,"verses":[176],"verseLabel":"الأعراف: 176","question":"لماذا عُدّي ﴿أخلد﴾ بـ﴿إلى﴾؟","answer":"﴿إلى﴾ تصور اتجاه ميله وقصده نحو الأرض حتى ركن إليها واستقر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص157–171.","url":""}]},{"id":"s7-1284","number":1284,"surah":7,"verses":[176],"verseLabel":"الأعراف: 176","question":"لماذا قابل الرفع بالإخلاد إلى الأرض؟","answer":"قوبل العلو الذي تمنحه الآيات بالسقوط إلى الأرض؛ فالمقابلة تجسد التفاوت بين طريق الوحي وطريق الشهوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص157–171.","url":""}]},{"id":"s7-1285","number":1285,"surah":7,"verses":[176],"verseLabel":"الأعراف: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿واتبع هواه﴾ بعد ﴿أخلد إلى الأرض﴾؟","answer":"الإخلاد يصف تعلقه بالدنيا، واتباع الهوى يبين القائد الداخلي لهذا التعلق؛ فاختار رغباته على الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص157–171.","url":""}]},{"id":"s7-1286","number":1286,"surah":7,"verses":[176],"verseLabel":"الأعراف: 176","question":"لماذا شُبّه بالكلب تحديدًا؟","answer":"لأن الكلب يلهث في حالتي الطرد والترك، فضرب به مثل من استولى عليه الطمع والهوى فلا يهدأ بالموعظة ولا بتركها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص157–171.","url":""}]},{"id":"s7-1287","number":1287,"surah":7,"verses":[176],"verseLabel":"الأعراف: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿إن تحمل عليه يلهث أو تتركه يلهث﴾؟","answer":"المعنى أن حاله واحدة: إن تزجره أو تعظه يظل تابعًا لهواه، وإن تتركه يظل كذلك؛ كدوام لهث الكلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص157–171.","url":""}]},{"id":"s7-1288","number":1288,"surah":7,"verses":[176],"verseLabel":"الأعراف: 176","question":"ما سرّ تقديم الحمل عليه على تركه؟","answer":"قدم الحمل لأنه صورة أشد تكشف لهث الكلب أولًا، ثم جاء الترك ليثبت أن اللهث طبع ملازم لا أثر تعب عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص157–171.","url":""}]},{"id":"s7-1289","number":1289,"surah":7,"verses":[176],"verseLabel":"الأعراف: 176","question":"لماذا كرر ﴿يلهث﴾؟","answer":"كرر الفعل لإثبات تساوي الحالتين واستقلال كل شرط بنتيجته؛ فهو يلهث في الشدة والراحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص157–171.","url":""}]},{"id":"s7-1290","number":1290,"surah":7,"verses":[176],"verseLabel":"الأعراف: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك مثل القوم الذين كذبوا بآياتنا﴾ بعد مثل الفرد؟","answer":"نقل المثل من الرجل الواحد إلى كل قوم يكذبون بالآيات؛ فحاله نموذج متكرر لا حادثة فردية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص157–171.","url":""}]},{"id":"s7-1291","number":1291,"surah":7,"verses":[176],"verseLabel":"الأعراف: 176","question":"لماذا أمر: ﴿فاقصص القصص لعلهم يتفكرون﴾؟","answer":"الأمر بتكرار عرض القصص ليحرك العقول؛ فالقصص ليس للتسلية بل لكشف سنن الانحراف وعواقبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص157–171.","url":""}]},{"id":"s7-1292","number":1292,"surah":7,"verses":[176],"verseLabel":"الأعراف: 176","question":"لماذا خُتمت بـ﴿لعلهم يتفكرون﴾ لا «يتذكرون»؟","answer":"التفكر هو النظر في تركيب المثل وأسبابه ومآله واستخراج العبرة، وهو أنسب من مجرد تذكر معلومة سابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص157–171.","url":""}]},{"id":"s7-1293","number":1293,"surah":7,"verses":[177],"verseLabel":"الأعراف: 177","question":"لماذا افتتحت بـ﴿ساء مثلًا﴾؟","answer":"بدأ بفعل الذم ليواجه السامع فورًا بقبح هذا المثل قبل إعادة وصف أصحابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص172–179.","url":""}]},{"id":"s7-1294","number":1294,"surah":7,"verses":[177],"verseLabel":"الأعراف: 177","question":"ما سرّ تقديم ﴿مثلًا﴾ على ﴿القوم﴾؟","answer":"تقديم ﴿مثلًا﴾ يركز الذم على الصورة العجيبة المضروبة لهم، ثم يبين أصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص172–179.","url":""}]},{"id":"s7-1295","number":1295,"surah":7,"verses":[177],"verseLabel":"الأعراف: 177","question":"لماذا أظهر ﴿القوم الذين كذبوا بآياتنا﴾ بدل الضمير؟","answer":"أظهر الموصول بدل الضمير لتكرير سبب الذم في السمع: تكذيبهم بآيات الله هو الذي جعل مثلهم سيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص172–179.","url":""}]},{"id":"s7-1296","number":1296,"surah":7,"verses":[177],"verseLabel":"الأعراف: 177","question":"ما سرّ التعبير في قوله تعالى: ﴿وأنفسهم كانوا يظلمون﴾؟","answer":"قدم ﴿أنفسهم﴾ وأدخل ﴿كانوا﴾ ليقرر أن ظلمهم راجع إليهم ومستمر؛ فالله لم يظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص172–179.","url":""}]},{"id":"s7-1297","number":1297,"surah":7,"verses":[177],"verseLabel":"الأعراف: 177","question":"لماذا قدّم ﴿أنفسهم﴾ على ﴿كانوا يظلمون﴾؟","answer":"التقديم يفيد القصر: لم تقع حقيقة ظلمهم إلا على أنفسهم، لأن عاقبة التكذيب عائدة إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص172–179.","url":""}]},{"id":"s7-1298","number":1298,"surah":7,"verses":[177],"verseLabel":"الأعراف: 177","question":"ما دلالة الجمع بين ﴿كانوا﴾ و﴿يظلمون﴾؟","answer":"تدل ﴿كانوا﴾ مع المضارع على أن ظلمهم كان شأنًا ثابتًا يتجدد منهم، لا حادثة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص172–179.","url":""}]},{"id":"s7-1299","number":1299,"surah":7,"verses":[178],"verseLabel":"الأعراف: 178","question":"ما سرّ الإفراد في ﴿فهو المهتدي﴾ والجمع في ﴿فأولئك هم الخاسرون﴾؟","answer":"روعي لفظ ﴿من﴾ المفرد في جانب الهداية، ثم روعي معناها العام في جانب الضلال؛ فجيء بالجمع لأن الخاسرين فريق كثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص180–187.","url":""}]},{"id":"s7-1300","number":1300,"surah":7,"verses":[178],"verseLabel":"الأعراف: 178","question":"ما سرّ إظهار اسم الله في ﴿من يهد الله﴾؟","answer":"أُظهر الاسم الجليل لتشريف الهداية والتنويه بأن مصدرها الله وحده، مع زيادة التقرير والوضوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص180–187.","url":""}]},{"id":"s7-1301","number":1301,"surah":7,"verses":[178],"verseLabel":"الأعراف: 178","question":"ما دلالة اسم الفاعل المعرّف في ﴿فهو المهتدي﴾؟","answer":"يفيد أن من هداه الله هو المتحقق بالهداية الكاملة الثابتة، وأنه المختص بحقيقتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص180–187.","url":""}]},{"id":"s7-1302","number":1302,"surah":7,"verses":[178],"verseLabel":"الأعراف: 178","question":"ما سرّ عدم إعادة اسم الله في قوله تعالى: ﴿ومن يضلل﴾؟","answer":"دل عليه ذكره في الشرط الأول، فحُذف تجنبًا للتكرار، وفي ذلك أدب بلاغي بإبعاد الاسم الجليل عن التصريح المتكرر بجانب الإضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص180–187.","url":""}]},{"id":"s7-1303","number":1303,"surah":7,"verses":[178],"verseLabel":"الأعراف: 178","question":"ما سرّ الانتقال إلى الجمع في جواب الشرط: ﴿فأولئك﴾؟","answer":"انتقل إلى الجمع مراعاةً لمعنى ﴿من﴾؛ فهي وإن أفرد لفظها تشمل كل من وقع في الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص180–187.","url":""}]},{"id":"s7-1304","number":1304,"surah":7,"verses":[178],"verseLabel":"الأعراف: 178","question":"ما دلالة ضمير الفصل ﴿هم﴾ في ﴿أولئك هم الخاسرون﴾؟","answer":"يفيد تقوية الحكم وقصر جنس الخسران الكامل عليهم؛ إذ خسروا أنفسهم والهداية والمآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص180–187.","url":""}]},{"id":"s7-1305","number":1305,"surah":7,"verses":[178],"verseLabel":"الأعراف: 178","question":"ما مناسبة مقابلة الهداية بالخسران بدل الضلال؟","answer":"لأن الضلال سبب، وعاقبته الجامعة هي الخسران؛ فالمقابلة انتقلت من الطريق الصحيح إلى نتيجة فقده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص180–187.","url":""}]},{"id":"s7-1306","number":1306,"surah":7,"verses":[179],"verseLabel":"الأعراف: 179","question":"ما دلالة التوكيد في ﴿ولقد ذرأنا لجهنم كثيرًا﴾؟","answer":"الواو والقسم المقدر واللام و﴿قد﴾ تؤكد الخبر وتقرره؛ لأنه خبر عظيم يكشف كثرة من أفضت بهم أعمالهم إلى جهنم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص188–208.","url":""}]},{"id":"s7-1307","number":1307,"surah":7,"verses":[179],"verseLabel":"الأعراف: 179","question":"ما سرّ التعبير بـ﴿ذرأنا﴾ بدل «خلقنا»؟","answer":"الذرء هو الخلق مع معنى الإيجاد والبث والتكثير، فناسب ذكر الكثير من الجن والإنس.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص188–208.","url":""}]},{"id":"s7-1308","number":1308,"surah":7,"verses":[179],"verseLabel":"الأعراف: 179","question":"ما دلالة اللام في ﴿لجهنم﴾؟","answer":"هي لام العاقبة والصيرورة: خلقهم مهيئين للاختيار، فاختاروا ما كانت عاقبته جهنم، وليست لام الغرض المكره لهم على المعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص188–208.","url":""}]},{"id":"s7-1309","number":1309,"surah":7,"verses":[179],"verseLabel":"الأعراف: 179","question":"ما سرّ تقديم الجن على الإنس؟","answer":"قُدموا لتقدم خلقهم، ولأن المقام يستوعب الصنفين المكلفين مبتدئًا بالأسبق وجودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص188–208.","url":""}]},{"id":"s7-1310","number":1310,"surah":7,"verses":[179],"verseLabel":"الأعراف: 179","question":"ما دلالة إسناد الفقه إلى القلوب في ﴿لهم قلوب لا يفقهون بها﴾؟","answer":"القلب في الاستعمال القرآني موضع الإدراك والتدبر والاعتبار؛ فنفي الفقه عنه نفي للانتفاع العقلي بالحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص188–208.","url":""}]},{"id":"s7-1311","number":1311,"surah":7,"verses":[179],"verseLabel":"الأعراف: 179","question":"ما سرّ تكرار ﴿لهم﴾ في ذكر القلوب والأعين والآذان؟","answer":"التكرار يفصل كل نعمة ويقرر قيام الحجة بها مستقلة؛ فقد عطلوا القلب والبصر والسمع جميعًا عن غاياتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص188–208.","url":""}]},{"id":"s7-1312","number":1312,"surah":7,"verses":[179],"verseLabel":"الأعراف: 179","question":"كيف يُفهم نفي الفقه والإبصار والسماع مع سلامة الجوارح؟","answer":"المنفي هو الانتفاع بهذه الجوارح في إدراك آيات الحق وقبولها، لا أصل وظائفها الحسية؛ فهي موجودة ولكنها معطلة عن غايتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص188–208.","url":""}]},{"id":"s7-1313","number":1313,"surah":7,"verses":[179],"verseLabel":"الأعراف: 179","question":"ما سرّ ترتيب القلوب ثم الأعين ثم الآذان؟","answer":"بدأ بالقلب لأنه محل الفقه والحكم، ثم ذكر العين والأذن لأنهما طريقا وصول المشاهدات والمسموعات إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص188–208.","url":""}]},{"id":"s7-1314","number":1314,"surah":7,"verses":[179],"verseLabel":"الأعراف: 179","question":"ما وجه تشبيههم بالأنعام في ﴿أولئك كالأنعام﴾؟","answer":"لأنهم حصروا مداركهم في المحسوس والشهوة ولم يستعملوها في معرفة الحق، فشابهوا الأنعام في الاقتصار على مطالب الجسد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص188–208.","url":""}]},{"id":"s7-1315","number":1315,"surah":7,"verses":[179],"verseLabel":"الأعراف: 179","question":"ما دلالة الترقي من ﴿كالأنعام﴾ إلى ﴿بل هم أضل﴾؟","answer":"هم أضل لأن الأنعام لم تُعطَ وسائل التكليف والتمييز ثم تعطلها، أما هؤلاء فأوتوا المدارك والحجة وأعرضوا عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص188–208.","url":""}]},{"id":"s7-1316","number":1316,"surah":7,"verses":[179],"verseLabel":"الأعراف: 179","question":"ما سرّ تكرار اسم الإشارة ﴿أولئك﴾؟","answer":"أعيد للتنبيه عليهم بعد تمام وصفهم، ولتثبيت حكم جديد مستقل: أنهم الغافلون حقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص188–208.","url":""}]},{"id":"s7-1317","number":1317,"surah":7,"verses":[179],"verseLabel":"الأعراف: 179","question":"ما مناسبة ختم الآية بـ﴿أولئك هم الغافلون﴾؟","answer":"الغفلة هي الجامع الذي نشأ عنه تعطيل القلب والعين والأذن، فجاء الختام كاشفًا أصل ضلالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص188–208.","url":""}]},{"id":"s7-1318","number":1318,"surah":7,"verses":[180],"verseLabel":"الأعراف: 180","question":"ما دلالة تقديم ﴿ولله﴾ في ﴿ولله الأسماء الحسنى﴾؟","answer":"التقديم يفيد الاختصاص: الأسماء البالغة غاية الحسن مختصة بالله على وجه الكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص209–222.","url":""}]},{"id":"s7-1319","number":1319,"surah":7,"verses":[180],"verseLabel":"الأعراف: 180","question":"ما دلالة جمع ﴿الأسماء﴾؟","answer":"الجمع يدل على تعدد الأسماء الدالة على صفات الكمال، مع وحدة المسمى سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص209–222.","url":""}]},{"id":"s7-1320","number":1320,"surah":7,"verses":[180],"verseLabel":"الأعراف: 180","question":"ما سرّ وصف الأسماء بـ﴿الحسنى﴾ بدل «الحسنة»؟","answer":"﴿الحسنى﴾ مؤنث الأحسن، فتدل على بلوغ أسماء الله الغاية العليا في الحسن والكمال، لا مجرد اتصافها بالحسن.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص209–222.","url":""}]},{"id":"s7-1321","number":1321,"surah":7,"verses":[180],"verseLabel":"الأعراف: 180","question":"ما مناسبة تفريع ﴿فادعوه بها﴾ على قوله تعالى: ﴿ولله الأسماء الحسنى﴾؟","answer":"لما ثبت اختصاصه بالأسماء الحسنى ترتب عليه أن يُدعى ويُثنى عليه بها، باختيار الاسم المناسب للمطلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص209–222.","url":""}]},{"id":"s7-1322","number":1322,"surah":7,"verses":[180],"verseLabel":"الأعراف: 180","question":"ما دلالة الباء في ﴿فادعوه بها﴾؟","answer":"الباء للاستعانة والتوسل المشروع؛ أي اجعلوا أسماءه الحسنى وسيلة في دعائه والثناء عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص209–222.","url":""}]},{"id":"s7-1323","number":1323,"surah":7,"verses":[180],"verseLabel":"الأعراف: 180","question":"ما سرّ الأمر بـ﴿وذروا الذين يلحدون في أسمائه﴾؟","answer":"المعنى: دعوا من يصرون على الإلحاد بعد قيام الحجة، ولا تتبعوا طريقتهم؛ فقد تولى الوعيد بيان جزائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص209–222.","url":""}]},{"id":"s7-1324","number":1324,"surah":7,"verses":[180],"verseLabel":"الأعراف: 180","question":"ما دلالة ﴿في﴾ في ﴿يلحدون في أسمائه﴾؟","answer":"تصور انحرافهم واقعًا في شأن الأسماء نفسها؛ بتغييرها أو تحريف معانيها أو إطلاق ما لا يليق بالله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص209–222.","url":""}]},{"id":"s7-1325","number":1325,"surah":7,"verses":[180],"verseLabel":"الأعراف: 180","question":"ما سرّ التعبير بـ﴿سيلقون ما كانوا يعملون﴾ بدل التصريح بالعذاب؟","answer":"صوّر الجزاء كأنه نفس أعمالهم التي يلقونها؛ تحقيقًا للمقابلة بين العمل وعاقبته، وتهويلًا لما ينتظرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص209–222.","url":""}]},{"id":"s7-1326","number":1326,"surah":7,"verses":[180],"verseLabel":"الأعراف: 180","question":"ما دلالة اختيار ﴿سيلقون﴾؟","answer":"اللقاء يدل على المواجهة والمصادفة المباشرة؛ فيوحي بأن جزاء أعمالهم آتٍ إليهم لا محيد عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص209–222.","url":""}]},{"id":"s7-1327","number":1327,"surah":7,"verses":[181],"verseLabel":"الأعراف: 181","question":"ما مناسبة قوله تعالى: ﴿وممن خلقنا أمة﴾ بعد ذكر من ذُرئوا لجهنم؟","answer":"جاءت مقابلةً للفريق الغافل؛ فكما وُجد الكثير المعرض، وُجدت جماعة مهتدية تقيم الحق والعدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص223–230.","url":""}]},{"id":"s7-1328","number":1328,"surah":7,"verses":[181],"verseLabel":"الأعراف: 181","question":"ما سرّ التعبير بـ﴿ممن خلقنا﴾ بدل «ومن الناس»؟","answer":"يعم اللفظ من خلقهم الله، وينبه إلى قدرته في إيجاد هذه الأمة المهتدية واختيارها من جملة خلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص223–230.","url":""}]},{"id":"s7-1329","number":1329,"surah":7,"verses":[181],"verseLabel":"الأعراف: 181","question":"ما دلالة تنكير ﴿أمة﴾؟","answer":"التنكير للتعظيم والتنويه بجماعة موصوفة بالهداية بالحق وإقامة العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص223–230.","url":""}]},{"id":"s7-1330","number":1330,"surah":7,"verses":[181],"verseLabel":"الأعراف: 181","question":"ما الفرق بين ﴿وممن خلقنا أمة يهدون بالحق﴾ و﴿ومن قوم موسى أمة يهدون بالحق﴾؟","answer":"آية 159 خصت جماعة من قوم موسى، أما آية 181 فعممت وجود أمة قائمة بالحق من خلق الله؛ فليس الثاني تكرارًا محضًا للأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص223–230.","url":""}]},{"id":"s7-1331","number":1331,"surah":7,"verses":[181],"verseLabel":"الأعراف: 181","question":"ما دلالة الباء في ﴿يهدون بالحق وبه يعدلون﴾، وما سرّ إعادة ﴿به﴾؟","answer":"الباء للملابسة والاستعانة؛ فهم يجعلون الحق دليل هدايتهم ومعيار حكمهم، وأعيد الضمير لتوكيد أن العدل نفسه لا ينفصل عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص223–230.","url":""}]},{"id":"s7-1332","number":1332,"surah":7,"verses":[182],"verseLabel":"الأعراف: 182","question":"ما مناسبة استئناف الوعيد بقوله تعالى: ﴿والذين كذبوا بآياتنا سنستدرجهم﴾؟","answer":"بعد ذكر الأمة القائمة بالحق عاد السياق إلى المكذبين ليبين أن إمهالهم ليس نجاة، بل استدراج يعقبه الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص231–235.","url":""}]},{"id":"s7-1333","number":1333,"surah":7,"verses":[182],"verseLabel":"الأعراف: 182","question":"ما الصورة التي يرسمها فعل ﴿سنستدرجهم﴾؟","answer":"يصور نقلهم درجة بعد درجة إلى الهلاك، مع توالي النعم والإمهال حتى يزدادوا اغترارًا وهم لا يشعرون بالمآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص231–235.","url":""}]},{"id":"s7-1334","number":1334,"surah":7,"verses":[182],"verseLabel":"الأعراف: 182","question":"ما دلالة صيغة الاستفعال في ﴿سنستدرجهم﴾؟","answer":"تفيد المعالجة والتدرج؛ أي أخذهم شيئًا فشيئًا ودرجة بعد درجة، لا بالعقوبة الفجائية أول الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص231–235.","url":""}]},{"id":"s7-1335","number":1335,"surah":7,"verses":[182],"verseLabel":"الأعراف: 182","question":"ما دلالة السين في ﴿سنستدرجهم﴾؟","answer":"تدل على تحقق الاستدراج فيما يستقبل واستمراره مرحلة بعد مرحلة، وفيها وعيد بما سيؤول إليه إمهالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص231–235.","url":""}]},{"id":"s7-1336","number":1336,"surah":7,"verses":[182],"verseLabel":"الأعراف: 182","question":"ما سرّ التعبير بـ﴿من حيث لا يعلمون﴾؟","answer":"يأتيهم الاستدراج من جهة لا يدركونها؛ إذ يحسبون النعم والإمهال إكرامًا، وهي طريق خفي إلى أخذهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص231–235.","url":""}]},{"id":"s7-1337","number":1337,"surah":7,"verses":[182],"verseLabel":"الأعراف: 182","question":"ما دلالة نفي العلم في ﴿لا يعلمون﴾؟","answer":"نفي العلم أعمق من نفي الإحساس العابر؛ فهم لا يفهمون حقيقة ما يجري ولا عاقبته، وإن شاهدوا ظاهره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص231–235.","url":""}]},{"id":"s7-1338","number":1338,"surah":7,"verses":[183],"verseLabel":"الأعراف: 183","question":"ما الصورة في قوله تعالى: ﴿وأملي لهم﴾؟","answer":"الإملاء إطالة المدة والإمهال، كمن يرخي الحبل لغيره؛ فيتمادون قبل أن يؤخذوا أخذًا محكمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص236–240.","url":""}]},{"id":"s7-1339","number":1339,"surah":7,"verses":[183],"verseLabel":"الأعراف: 183","question":"ما دلالة اللام في ﴿وأملي لهم﴾؟","answer":"تصور الإمهال في ظاهره واقعًا لمصلحتهم؛ فيزدادون اغترارًا، مع أن عاقبته الأخذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص236–240.","url":""}]},{"id":"s7-1340","number":1340,"surah":7,"verses":[183],"verseLabel":"الأعراف: 183","question":"ما سرّ الانتقال من ﴿سنستدرجهم﴾ إلى ﴿وأملي﴾ بالإفراد؟","answer":"جاء الإملاء بصيغة المتكلم المفرد لإبرازه فعلًا صادرًا عن الإرادة الإلهية مباشرة، بعد صيغة التعظيم في الاستدراج.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص236–240.","url":""}]},{"id":"s7-1341","number":1341,"surah":7,"verses":[183],"verseLabel":"الأعراف: 183","question":"ما دلالة التوكيد في ﴿إن كيدي متين﴾؟","answer":"يؤكد أن الإمهال ليس عجزًا ولا إفلاتًا، وأن التدبير الذي ينتهي بأخذهم ثابت لا يتخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص236–240.","url":""}]},{"id":"s7-1342","number":1342,"surah":7,"verses":[183],"verseLabel":"الأعراف: 183","question":"ما وجه تسمية الجزاء الإلهي ﴿كيدًا﴾؟","answer":"سُمي كيدًا على سبيل المشاكلة؛ لأنه تدبير خفي يقابل كيدهم ويجازيهم عليه، مع تنزه فعل الله عن الظلم والنقص.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص236–240.","url":""}]},{"id":"s7-1343","number":1343,"surah":7,"verses":[183],"verseLabel":"الأعراف: 183","question":"ما دلالة وصف الكيد بـ﴿متين﴾؟","answer":"﴿متين﴾ أي شديد قوي محكم لا يُدفع ولا يُنقض؛ فناسب حتمية الأخذ بعد الإمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص236–240.","url":""}]},{"id":"s7-1344","number":1344,"surah":7,"verses":[184],"verseLabel":"الأعراف: 184","question":"ما دلالة التوبيخ في ﴿أولم يتفكروا﴾؟","answer":"ينكر عليهم ترك التفكر الذي يكشف بطلان دعوى الجنون، مع وضوح سيرة النبي بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص241–248.","url":""}]},{"id":"s7-1345","number":1345,"surah":7,"verses":[184],"verseLabel":"الأعراف: 184","question":"ما سرّ اختيار ﴿يتفكروا﴾ بدل «يعلموا»؟","answer":"المطلوب أن يعملوا النظر في سيرته ودعوته حتى يصلوا بأنفسهم إلى انتفاء الجنون، لا أن يتلقوا مجرد خبر بذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص241–248.","url":""}]},{"id":"s7-1346","number":1346,"surah":7,"verses":[184],"verseLabel":"الأعراف: 184","question":"ما دلالة وصف النبي ﷺ بأنه ﴿صاحبهم﴾؟","answer":"يذكرهم بطول صحبته ومخالطته لهم، فقد عرفوا عقله وصدقه قبل الرسالة؛ وذلك أقطع لدعوى الجنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص241–248.","url":""}]},{"id":"s7-1347","number":1347,"surah":7,"verses":[184],"verseLabel":"الأعراف: 184","question":"ما دلالة ﴿من﴾ في ﴿ما بصاحبهم من جنة﴾؟","answer":"زيدت بعد النفي لاستغراق الجنس؛ أي ليس به أدنى شيء من الجنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص241–248.","url":""}]},{"id":"s7-1348","number":1348,"surah":7,"verses":[184],"verseLabel":"الأعراف: 184","question":"ما سرّ التعبير عن الجنون بـ﴿جنة﴾؟","answer":"أصلها الستر، فالجنون يستر العقل ويحجبه عن عمله؛ واختيار اللفظ يرد دعواهم من أصل معناها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص241–248.","url":""}]},{"id":"s7-1349","number":1349,"surah":7,"verses":[184],"verseLabel":"الأعراف: 184","question":"ما دلالة القصر في ﴿إن هو إلا نذير مبين﴾؟","answer":"يقصر شأنه في هذا المقام على الرسالة والإنذار الواضح، وينفي عنه ما افتروه من الجنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص241–248.","url":""}]},{"id":"s7-1350","number":1350,"surah":7,"verses":[184],"verseLabel":"الأعراف: 184","question":"ما مناسبة وصفه ﷺ هنا بـ﴿نذير﴾؟","answer":"لأن الخطاب لمكذبين معرضين يتهددهم الاستدراج واقتراب الأجل، فناسبهم الإنذار قبل البشارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص241–248.","url":""}]},{"id":"s7-1351","number":1351,"surah":7,"verses":[184],"verseLabel":"الأعراف: 184","question":"ما دلالة وصف النذير بـ﴿مبين﴾؟","answer":"هو بيّن الرسالة، مظهر لما ينذر به بعبارة واضحة تقوم بها الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص241–248.","url":""}]},{"id":"s7-1352","number":1352,"surah":7,"verses":[185],"verseLabel":"الأعراف: 185","question":"ما مناسبة الانتقال من ﴿أولم يتفكروا﴾ إلى ﴿أولم ينظروا﴾؟","answer":"دعاهم أولًا إلى التفكر في الرسول الذي يعرفونه، ثم وسع مجال النظر إلى ملكوت السماوات والأرض وسائر المخلوقات.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص249–263.","url":""}]},{"id":"s7-1353","number":1353,"surah":7,"verses":[185],"verseLabel":"الأعراف: 185","question":"ما دلالة ﴿ملكوت﴾ بدل «ملك»؟","answer":"صيغة ﴿ملكوت﴾ تفيد عظمة الملك وسعته وإحكام السلطان، فتدعو إلى تدبر دلائل القدرة في الكون.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص249–263.","url":""}]},{"id":"s7-1354","number":1354,"surah":7,"verses":[185],"verseLabel":"الأعراف: 185","question":"ما دلالة ﴿في﴾ في ﴿ينظروا في ملكوت السماوات والأرض﴾؟","answer":"تجعل الملكوت مجالًا يتعمق فيه النظر والتدبر، لا مجرد شيء يمر عليه البصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص249–263.","url":""}]},{"id":"s7-1355","number":1355,"surah":7,"verses":[185],"verseLabel":"الأعراف: 185","question":"ما سرّ الجمع بين ﴿ملكوت السماوات والأرض﴾ و﴿ما خلق الله من شيء﴾؟","answer":"جمع بين النظر في النظام الكوني العظيم والنظر في كل مخلوق مفرد؛ لتعم دلائل القدرة الكليات والجزئيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص249–263.","url":""}]},{"id":"s7-1356","number":1356,"surah":7,"verses":[185],"verseLabel":"الأعراف: 185","question":"ما دلالة ﴿من﴾ في ﴿ما خلق الله من شيء﴾؟","answer":"تؤكد العموم بعد النفي؛ فلا يخرج شيء من المخلوقات عن كونه مجالًا للنظر والدلالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص249–263.","url":""}]},{"id":"s7-1357","number":1357,"surah":7,"verses":[185],"verseLabel":"الأعراف: 185","question":"ما مناسبة عطف ﴿وأن عسى أن يكون قد اقترب أجلهم﴾؟","answer":"أضاف إلى حجة الكون باعثًا شخصيًا عاجلًا: قد يدنو موتهم فلا تبقى لهم مهلة للإيمان والتدبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص249–263.","url":""}]},{"id":"s7-1358","number":1358,"surah":7,"verses":[185],"verseLabel":"الأعراف: 185","question":"ما دلالة اجتماع ﴿عسى﴾ و﴿أن يكون﴾ و﴿قد اقترب﴾؟","answer":"﴿عسى﴾ تفتح احتمالًا مخوفًا، و﴿أن يكون﴾ تصوغه واقعًا ممكنًا، و﴿قد﴾ تقرب حصوله؛ فتتراكم الدلالات للحث على المبادرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص249–263.","url":""}]},{"id":"s7-1359","number":1359,"surah":7,"verses":[185],"verseLabel":"الأعراف: 185","question":"ما دلالة الاستفهام في ﴿فبأي حديث بعده يؤمنون﴾؟","answer":"استفهام إنكاري يقرر أنه إذا لم يحملهم القرآن على الإيمان، فلا حديث بعده أحق أن يؤمنوا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص249–263.","url":""}]},{"id":"s7-1360","number":1360,"surah":7,"verses":[185],"verseLabel":"الأعراف: 185","question":"ما مرجع الضمير في ﴿بعده﴾؟","answer":"يعود إلى القرآن، وهو الحديث الذي جاءهم به الرسول وأنذرهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص249–263.","url":""}]},{"id":"s7-1361","number":1361,"surah":7,"verses":[186],"verseLabel":"الأعراف: 186","question":"ما مناسبة قوله تعالى: ﴿من يضلل الله فلا هادي له﴾ بعد الدعوة إلى النظر؟","answer":"يبين أن من أعرض عن دلائل الهداية حتى خُذل لا تنفعه كثرة الآيات، ولا يستطيع أحد أن يهديه من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص264–270.","url":""}]},{"id":"s7-1362","number":1362,"surah":7,"verses":[186],"verseLabel":"الأعراف: 186","question":"ما دلالة ﴿لا﴾ النافية للجنس في ﴿فلا هادي له﴾؟","answer":"تنفي وجود أي هادٍ له نفيًا شاملًا، فتقرر انفراد الله بالهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص264–270.","url":""}]},{"id":"s7-1363","number":1363,"surah":7,"verses":[186],"verseLabel":"الأعراف: 186","question":"ما دلالة إفراد ﴿هادي﴾؟","answer":"جاء نكرة في سياق النفي فيعم كل فرد من جنس الهداة؛ فلا يوجد له هادٍ واحد أيًا كان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص264–270.","url":""}]},{"id":"s7-1364","number":1364,"surah":7,"verses":[186],"verseLabel":"الأعراف: 186","question":"ما سرّ التعبير بـ﴿ويذرهم﴾ بدل «ويتركهم»؟","answer":"﴿يذرهم﴾ أدل على الإهمال والتخلية بعد الإعراض، وفيها وعيد بأنهم يُتركون لعاقبة اختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص264–270.","url":""}]},{"id":"s7-1365","number":1365,"surah":7,"verses":[186],"verseLabel":"الأعراف: 186","question":"ما الصورة في قوله تعالى: ﴿في طغيانهم﴾؟","answer":"صُور الطغيان ظرفًا يحيط بهم ويستغرقهم؛ فهم مغمورون في مجاوزة الحد لا يخرجون منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص264–270.","url":""}]},{"id":"s7-1366","number":1366,"surah":7,"verses":[186],"verseLabel":"الأعراف: 186","question":"ما دلالة إضافة الطغيان إليهم في ﴿طغيانهم﴾؟","answer":"تنسب الطغيان إلى اختيارهم وكسبهم؛ فهو طغيان صدر منهم واستقر فيهم، لا ظلم فُرض عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص264–270.","url":""}]},{"id":"s7-1367","number":1367,"surah":7,"verses":[186],"verseLabel":"الأعراف: 186","question":"ما دلالة ﴿يعمهون﴾ بدل «يضلون»؟","answer":"العمه هو التحير والتردد مع عمى البصيرة؛ فهو يصور اضطرابهم داخل الطغيان، لا مجرد مفارقة الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص264–270.","url":""}]},{"id":"s7-1368","number":1368,"surah":7,"verses":[187],"verseLabel":"الأعراف: 187","question":"ما دلالة المضارع في ﴿يسألونك عن الساعة﴾؟","answer":"يصور تجدد سؤالهم وتكراره، سواء كان سؤال اختبار أو استهزاء أو استعلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص271–290.","url":""}]},{"id":"s7-1369","number":1369,"surah":7,"verses":[187],"verseLabel":"الأعراف: 187","question":"ما دلالة تسمية القيامة ﴿الساعة﴾؟","answer":"سميت بذلك لأنها تأتي بغتة في ساعة محددة، ولسرعة قيامها وقرب أمرها مهما طال الانتظار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص271–290.","url":""}]},{"id":"s7-1370","number":1370,"surah":7,"verses":[187],"verseLabel":"الأعراف: 187","question":"ما الصورة في سؤالهم: ﴿أيان مرساها﴾؟","answer":"شُبهت الساعة بسفينة مضطربة لا يعلم الناس متى تستقر وترسو؛ فالسؤال عن وقت ثبوت وقوعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص271–290.","url":""}]},{"id":"s7-1371","number":1371,"surah":7,"verses":[187],"verseLabel":"الأعراف: 187","question":"ما دلالة إضافة المرساة إلى الساعة في ﴿مرساها﴾؟","answer":"تجعل للساعة موعدًا خاصًا تستقر عنده وتقع، لا يتقدم ولا يتأخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص271–290.","url":""}]},{"id":"s7-1372","number":1372,"surah":7,"verses":[187],"verseLabel":"الأعراف: 187","question":"ما دلالة القصر في ﴿إنما علمها عند ربي﴾؟","answer":"يقصر علم وقت الساعة على الله وحده، وينفيه عن الرسول وعن كل مخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص271–290.","url":""}]},{"id":"s7-1373","number":1373,"surah":7,"verses":[187],"verseLabel":"الأعراف: 187","question":"ما سرّ التعبير أولًا بـ﴿عند ربي﴾ ثم بـ﴿عند الله﴾؟","answer":"جاء ﴿ربي﴾ في جواب النبي عن علمه ليظهر افتقاره إلى من يربيه بالوحي، ثم جاء الاسم الجليل في الحكم العام لتقرير اختصاص الله بعلمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص271–290.","url":""}]},{"id":"s7-1374","number":1374,"surah":7,"verses":[187],"verseLabel":"الأعراف: 187","question":"ما الصورة في قوله تعالى: ﴿لا يجليها لوقتها إلا هو﴾؟","answer":"شُبه خفاء الساعة بشيء مستور لا يكشفه ويظهره في موعده إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص271–290.","url":""}]},{"id":"s7-1375","number":1375,"surah":7,"verses":[187],"verseLabel":"الأعراف: 187","question":"ما دلالة تقديم ﴿لوقتها﴾ في ﴿لا يجليها لوقتها إلا هو﴾؟","answer":"يبرز أن تجليها مرتبط بوقتها المقدر تحديدًا، ثم يقصر كشفها في ذلك الوقت على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص271–290.","url":""}]},{"id":"s7-1376","number":1376,"surah":7,"verses":[187],"verseLabel":"الأعراف: 187","question":"ما دلالة قوله تعالى: ﴿ثقلت في السماوات والأرض﴾؟","answer":"عظُم أمرها وخفي علمها على أهل السماوات والأرض، وثقل ما يصاحبها من أهوال وتبدل للنظام الكوني.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص271–290.","url":""}]},{"id":"s7-1377","number":1377,"surah":7,"verses":[187],"verseLabel":"الأعراف: 187","question":"ما سرّ الجمع بين السماوات والأرض في ثقل الساعة؟","answer":"يفيد عموم شأنها لجميع العالم العلوي والسفلي، وأن علم وقتها محجوب عن الخلق كلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص271–290.","url":""}]},{"id":"s7-1378","number":1378,"surah":7,"verses":[187],"verseLabel":"الأعراف: 187","question":"ما دلالة القصر في ﴿لا تأتيكم إلا بغتة﴾؟","answer":"يقصر مجيئها على المباغتة؛ فلا تسبقها معرفة بوقتها تتيح الاستعداد عند حلوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص271–290.","url":""}]},{"id":"s7-1379","number":1379,"surah":7,"verses":[187],"verseLabel":"الأعراف: 187","question":"ما سرّ تكرار ﴿يسألونك﴾ في الآية؟","answer":"الأول حكاية لسؤالهم عن وقت الساعة، والثاني يكشف هيئة سؤالهم كأنهم يظنون النبي بالغ الاستقصاء في علمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص271–290.","url":""}]},{"id":"s7-1380","number":1380,"surah":7,"verses":[187],"verseLabel":"الأعراف: 187","question":"ما معنى ﴿حفي﴾ في ﴿كأنك حفي عنها﴾؟","answer":"الحفي هو المستقصي المبالغ في السؤال حتى يظن أنه أحاط بالخبر؛ والمعنى أنهم يسألونك كأنك شديد العناية بعلم وقتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص271–290.","url":""}]},{"id":"s7-1381","number":1381,"surah":7,"verses":[187],"verseLabel":"الأعراف: 187","question":"ما مناسبة ختم الآية بـ﴿ولكن أكثر الناس لا يعلمون﴾؟","answer":"أكثر الناس لا يعلمون أن وقت الساعة مما استأثر الله بعلمه، ولا يدركون حكمة إخفائه؛ لذلك يكررون السؤال عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص271–290.","url":""}]},{"id":"s7-1382","number":1382,"surah":7,"verses":[187],"verseLabel":"الأعراف: 187","question":"ما دلالة نفي العلم عن أكثر الناس بعد قصر علم الساعة على الله؟","answer":"يقرر أن جهلهم ليس بموعدها وحده، بل بحقيقة اختصاص الله بعلمها وبالحكمة من إخفائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص271–290.","url":""}]},{"id":"s7-1383","number":1383,"surah":7,"verses":[188],"verseLabel":"الأعراف: 188","question":"ما مناسبة الأمر للنبي ﷺ أن يقول: ﴿لا أملك لنفسي نفعًا ولا ضرًا﴾؟","answer":"يرد توهم أن الرسالة تستلزم امتلاك الغيب أو التصرف المستقل؛ فالرسول عبد لا يملك لنفسه شيئًا إلا بمشيئة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص291–310.","url":""}]},{"id":"s7-1384","number":1384,"surah":7,"verses":[188],"verseLabel":"الأعراف: 188","question":"ما سرّ تقديم ﴿نفعًا﴾ على ﴿ضرًا﴾ في هذا الموضع؟","answer":"ناسب ترتيب السياق؛ فقد تقدم ذكر الهداية قبل الضلال، ثم جاء بعده الاستكثار من الخير قبل مس السوء، فجرى النفع والضر على هذا النسق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص291–310؛ وأسرار التكرار في القرآن، ص130.","url":""}]},{"id":"s7-1385","number":1385,"surah":7,"verses":[188],"verseLabel":"الأعراف: 188","question":"كيف يُفهم قوله تعالى: ﴿لا أملك لنفسي﴾ مع وجود أسباب وتصرفات بشرية ظاهرة؟","answer":"المنفي هو الملك المستقل والقدرة الذاتية النافذة؛ أما مباشرة الأسباب فواقعة بما أقدر الله عليه وتحت مشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص291–310.","url":""}]},{"id":"s7-1386","number":1386,"surah":7,"verses":[188],"verseLabel":"الأعراف: 188","question":"ما دلالة الاستثناء في ﴿إلا ما شاء الله﴾؟","answer":"يثبت أن ما يحصل للنبي من نفع أو دفع ضر إنما يكون بما شاءه الله وأقدره عليه، لا بملك مستقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص291–310.","url":""}]},{"id":"s7-1387","number":1387,"surah":7,"verses":[188],"verseLabel":"الأعراف: 188","question":"ما دلالة الشرط في ﴿ولو كنت أعلم الغيب لاستكثرت من الخير﴾؟","answer":"أقام برهانًا عمليًا على انتفاء علم الغيب المستقل: لو علم المستقبل لطلب وجوه الخير كلها قبل فواتها وتجنب السوء قبل وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص291–310.","url":""}]},{"id":"s7-1388","number":1388,"surah":7,"verses":[188],"verseLabel":"الأعراف: 188","question":"ما دلالة ﴿استكثرت﴾ بدل «أخذت كثيرًا»؟","answer":"صيغة الاستفعال تدل على طلب الزيادة وتحصيل أكبر قدر ممكن من الخير، وهو الأليق بفرض العلم بالغيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص291–310.","url":""}]},{"id":"s7-1389","number":1389,"surah":7,"verses":[188],"verseLabel":"الأعراف: 188","question":"ما دلالة تعريف ﴿الخير﴾؟","answer":"يفيد جنس الخير واستيعاب وجوهه التي يمكن تحصيلها لو عُلم الغيب، لا خيرًا واحدًا محدودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص291–310.","url":""}]},{"id":"s7-1390","number":1390,"surah":7,"verses":[188],"verseLabel":"الأعراف: 188","question":"ما سرّ التعبير بـ﴿وما مسني السوء﴾ بدل «ولدفعت الضر»؟","answer":"جعل عدم إصابة السوء نتيجة لازمة لعلم الغيب المفترض، وصوّر السلامة تامة حتى إن السوء لا يقع منه أدنى مس.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص291–310.","url":""}]},{"id":"s7-1391","number":1391,"surah":7,"verses":[188],"verseLabel":"الأعراف: 188","question":"ما دلالة اختيار ﴿مسني﴾؟","answer":"المس أخف درجات الإصابة، فنفيه أبلغ في نفي كل ما فوقه من حلول السوء والضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص291–310.","url":""}]},{"id":"s7-1392","number":1392,"surah":7,"verses":[188],"verseLabel":"الأعراف: 188","question":"ما دلالة القصر في ﴿إن أنا إلا نذير وبشير﴾؟","answer":"يقصر وظيفته في هذا المقام على تبليغ الإنذار والبشارة، وينفي ما توهموه من علم الغيب أو التصرف المستقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص291–310.","url":""}]},{"id":"s7-1393","number":1393,"surah":7,"verses":[188],"verseLabel":"الأعراف: 188","question":"ما سرّ تقديم ﴿نذير﴾ على ﴿بشير﴾؟","answer":"لأن السياق خطاب للمكذبين السائلين عن الساعة، فكان التحذير من عاقبتهم أسبق، ثم أتبع ببشارة المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص291–310.","url":""}]},{"id":"s7-1394","number":1394,"surah":7,"verses":[188],"verseLabel":"الأعراف: 188","question":"ما دلالة تقييد الإنذار والبشارة بـ﴿لقوم يؤمنون﴾؟","answer":"الرسالة عامة، لكن المؤمنين هم الذين ينتفعون بالإنذار والبشارة ويصدقون بمقتضاهما؛ فالقيد للانتفاع لا لعموم البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص291–310.","url":""}]},{"id":"s7-1395","number":1395,"surah":7,"verses":[188],"verseLabel":"الأعراف: 188","question":"ما دلالة المضارع في ﴿قوم يؤمنون﴾؟","answer":"يصور إيمانهم متجددًا مستمرًا، يتلقى آيات الإنذار والبشارة فيزداد بها ثباتًا وعملًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص291–310.","url":""}]},{"id":"s7-1396","number":1396,"surah":7,"verses":[49],"verseLabel":"الأعراف: 188؛ يونس: 49","question":"ما سرّ تقديم النفع على الضر في الأعراف، وتقديم الضر على النفع في يونس؟","answer":"في الأعراف سبق تقديم الهداية على الضلال، ولحق الآية تقديم الخير على السوء، فناسب ﴿نفعًا ولا ضرًا﴾. وفي يونس سبق تكرار ذكر الضر، فجرى قوله ﴿ضرًا ولا نفعًا﴾ على الأصل وعلى نسق سياق السورة.","sources":[{"label":"الكرماني، أسرار التكرار في القرآن، ص130، «تفسير سورة الأعراف» على موقع إسلام ويب.","url":""}]},{"id":"s7-1397","number":1397,"surah":7,"verses":[189],"verseLabel":"الأعراف: 189","question":"ما مناسبة افتتاح الآية بقوله تعالى: ﴿هو الذي خلقكم﴾؟","answer":"لما سبق سؤالهم عن الساعة وإنكار بعضهم البعث، ذُكّروا ببدء خلق الإنسان؛ فمن قدر على الإنشاء أولًا قدر على الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1398","number":1398,"surah":7,"verses":[189],"verseLabel":"الأعراف: 189","question":"ما سرّ التعبير بـ﴿من نفس واحدة﴾؟","answer":"يقرر وحدة الأصل الإنساني؛ فالناس جميعًا متفرعون من آدم، وفي ذلك إظهار لقدرة الله ووحدة الخالق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1399","number":1399,"surah":7,"verses":[189],"verseLabel":"الأعراف: 189","question":"ما دلالة تنكير ﴿نفس﴾ ووصفها بـ﴿واحدة﴾؟","answer":"التنكير ثم الوصف يبرزان أن هذا الجنس البشري الكثير نشأ من نفس واحدة لا من أصول متفرقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1400","number":1400,"surah":7,"verses":[189],"verseLabel":"الأعراف: 189","question":"ما سرّ التعبير بـ﴿وجعل منها زوجها﴾ بدل «وخلق زوجًا آخر»؟","answer":"﴿منها﴾ تبين اتحاد الأصل والجنس، و﴿جعل﴾ يبرز تهيئتها لتكون زوجًا وسكنًا، لا مجرد إيجاد مخلوق آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1401","number":1401,"surah":7,"verses":[189],"verseLabel":"الأعراف: 189","question":"ما دلالة إضافة الزوج إلى النفس في ﴿زوجها﴾؟","answer":"تفيد شدة الاختصاص والاقتران؛ فهي الزوج الملائم لهذه النفس، ومن جنسها، والمهيأ لسكونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1402","number":1402,"surah":7,"verses":[189],"verseLabel":"الأعراف: 189","question":"ما الفرق بين ﴿ليسكن إليها﴾ و«ليسكن معها»؟","answer":"السكون إليها هو الميل والأنس والطمأنينة والركون، أما السكن معها فلا يتجاوز الدلالة على الاجتماع في مكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1403","number":1403,"surah":7,"verses":[189],"verseLabel":"الأعراف: 189","question":"ما سرّ إسناد السكون إلى الرجل في ﴿ليسكن إليها﴾؟","answer":"عاد الضمير إلى ﴿نفس واحدة﴾ باعتبار المراد بها آدم، وذكر علة جعل الزوج؛ ولا ينفي ذلك سكون كل من الزوجين إلى الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1404","number":1404,"surah":7,"verses":[189],"verseLabel":"الأعراف: 189","question":"ما بلاغة الكناية في قوله تعالى: ﴿فلما تغشاها﴾؟","answer":"كنى عن اتصال الزوج بزوجته بلفظ الغشيان، وهو الستر والتغطية؛ صونًا للعبارة وتصويرًا لشدة القرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1405","number":1405,"surah":7,"verses":[189],"verseLabel":"الأعراف: 189","question":"ما دلالة الفاء في ﴿فحملت حملًا خفيفًا﴾؟","answer":"تفيد التعقيب والسببية؛ فالحمل ترتب على الغشيان واتصل به في سياق أطوار التكوين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1406","number":1406,"surah":7,"verses":[189],"verseLabel":"الأعراف: 189","question":"ما دلالة الجمع بين الفعل والمصدر في ﴿حملت حملًا﴾؟","answer":"﴿حملًا﴾ مفعول به لا مصدر مؤكد؛ أي حملت جنينًا، ثم وصفه بالخفة، فليس في التركيب تكرار للمعنى نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1407","number":1407,"surah":7,"verses":[189],"verseLabel":"الأعراف: 189","question":"ما دلالة وصف الحمل أولًا بـ﴿خفيفًا﴾؟","answer":"يصور أول الحمل حين لا تجد المرأة ثقله ولا يشق عليها، تمهيدًا للمقابلة مع قوله: ﴿فلما أثقلت﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1408","number":1408,"surah":7,"verses":[189],"verseLabel":"الأعراف: 189","question":"ما دلالة المرور في قوله تعالى: ﴿فمرت به﴾؟","answer":"أي استمرت بالحمل في شؤونها، تقوم وتقعد من غير أن يثقلها؛ فالمرور يصور مضي هذا الطور بسهولة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1409","number":1409,"surah":7,"verses":[189],"verseLabel":"الأعراف: 189","question":"ما سرّ التعبير بـ﴿فلما أثقلت﴾ من غير ذكر الحمل؟","answer":"دل السياق على الحمل فحُذف إيجازًا، وجاءت الهمزة للصيرورة؛ أي دخلت في طور الثقل حين كبر الجنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1410","number":1410,"surah":7,"verses":[189],"verseLabel":"الأعراف: 189","question":"ما سرّ الانتقال إلى التثنية في ﴿دعوا الله ربهما﴾؟","answer":"لأن ثقل الحمل وسلامة الولد يعنيان الأبوين معًا، فاشتركا في الخوف والدعاء بعد أن كان وصف الحمل خاصًا بالأم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1411","number":1411,"surah":7,"verses":[189],"verseLabel":"الأعراف: 189","question":"ما دلالة الجمع بين اسم الجلالة ووصف الربوبية في ﴿دعوا الله ربهما﴾؟","answer":"أظهر اسم الله لقصر الدعاء عليه، ثم وصفه بربهما لاستحضار رعايته وقدرته على إتمام الخلق وإصلاح الولد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1412","number":1412,"surah":7,"verses":[189],"verseLabel":"الأعراف: 189","question":"ما دلالة تنكير ﴿صالحًا﴾ في ﴿لئن آتيتنا صالحًا﴾؟","answer":"حُذف الموصوف، أي ولدًا صالحًا، والتنكير يعم وجوه الصلاح: سلامة الخلق والعقل والفطرة والدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1413","number":1413,"surah":7,"verses":[189],"verseLabel":"الأعراف: 189","question":"ما دلالة توكيد ﴿لنكونن من الشاكرين﴾؟","answer":"لام جواب القسم ونون التوكيد الثقيلة تدلان على شدة الرغبة في إجابة الدعاء وقوة التزامهما بالشكر إن رُزقا الولد الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1414","number":1414,"surah":7,"verses":[190],"verseLabel":"الأعراف: 190","question":"ما سرّ إعادة ﴿صالحًا﴾ في قوله تعالى: ﴿فلما آتاهما صالحًا﴾؟","answer":"يثبت تمام إجابة الدعاء بعين المطلوب الذي سألاه؛ فقد آتاهما ولدًا مستوفيًا وصف الصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1415","number":1415,"surah":7,"verses":[190],"verseLabel":"الأعراف: 190","question":"من المراد بقوله تعالى: ﴿جعلا له شركاء فيما آتاهما﴾؟","answer":"الآية تضرب مثلًا للوالدين من ذرية آدم اللذين يشركان بعد أن يسألا الله الولد؛ فلا يصح نسبة الشرك إلى آدم وحواء، وهو ما يؤيده انتقال السياق إلى جمع ﴿يشركون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1416","number":1416,"surah":7,"verses":[190],"verseLabel":"الأعراف: 190","question":"ما دلالة جمع ﴿شركاء﴾ في قوله تعالى: ﴿جعلا له شركاء﴾؟","answer":"الجمع يناسب تعدد صور الشرك والمعبودات التي ينسب إليها المشركون نصيبًا من نعمة الولد، ولا يسند الآية إلى قصة اسم واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1417","number":1417,"surah":7,"verses":[190],"verseLabel":"الأعراف: 190","question":"ما دلالة قوله تعالى: ﴿فيما آتاهما﴾ بعد سبق ذكر العطاء؟","answer":"يعيد ربط الشرك بالنعمة نفسها؛ فموضع التوبيخ أنهم جعلوا لله شركاء في الولد الذي علموا أنه عطاء منه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1418","number":1418,"surah":7,"verses":[190],"verseLabel":"الأعراف: 190","question":"ما سرّ الانتقال من التثنية إلى الجمع في ﴿عما يشركون﴾؟","answer":"انتقل من مثال الأبوين إلى عموم المشركين الموجودين؛ فالجملة نتيجة تعم أصناف شركهم، وتدل على أن المراد ليس آدم وحواء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1419","number":1419,"surah":7,"verses":[190],"verseLabel":"الأعراف: 190","question":"ما دلالة الفاء في ﴿فتعالى الله﴾؟","answer":"تفيد أن تنزيه الله مترتب على ما فُصل من انفراده بالخلق والعطاء، وهي دلائل تبطل الشرك وتوجب التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1420","number":1420,"surah":7,"verses":[190],"verseLabel":"الأعراف: 190","question":"ما دلالة اختيار ﴿تعالى﴾ في تنزيه الله عن شركهم؟","answer":"يدل على علو الله وتنزهه وتقدسه عن أن يكون له شريك؛ وهو أبلغ من مجرد إعلان البراءة من فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311–341.","url":""}]},{"id":"s7-1421","number":1421,"surah":7,"verses":[191],"verseLabel":"الأعراف: 191","question":"ما دلالة الاستفهام في ﴿أيشركون ما لا يخلق شيئًا﴾؟","answer":"استفهام إنكاري للتوبيخ والتعجيب من تسويتهم المخلوق العاجز بالخالق القادر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص342–360.","url":""}]},{"id":"s7-1422","number":1422,"surah":7,"verses":[191],"verseLabel":"الأعراف: 191","question":"ما سرّ التعبير عن الأصنام بـ﴿ما﴾؟","answer":"استُعملت ﴿ما﴾ لأنها لغير العاقل، وفي ذلك كشف لحقيقة الأصنام الجمادية وإبطال لما رفعها إليه عابدوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص342–360.","url":""}]},{"id":"s7-1423","number":1423,"surah":7,"verses":[191],"verseLabel":"الأعراف: 191","question":"ما دلالة ﴿شيئًا﴾ في ﴿لا يخلق شيئًا﴾؟","answer":"جاءت نكرة في سياق النفي فعمّت؛ أي لا تخلق شيئًا مهما صغر، فانتفى عنها أصل القدرة على الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص342–360.","url":""}]},{"id":"s7-1424","number":1424,"surah":7,"verses":[191],"verseLabel":"الأعراف: 191","question":"ما سرّ جمع ضمير الأصنام في ﴿وهم يُخلقون﴾ بعد التعبير عنها بـ﴿ما﴾؟","answer":"روعي في ﴿ما﴾ حقيقتها غير العاقلة، ثم روعي في ضمير الجمع ما نزله المشركون منزلة العقلاء حين عبدوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص342–360.","url":""}]},{"id":"s7-1425","number":1425,"surah":7,"verses":[191],"verseLabel":"الأعراف: 191","question":"ما دلالة بناء ﴿يُخلقون﴾ للمجهول؟","answer":"يوجه النظر إلى وصفهم الحاسم: أنهم مصنوعون مخلوقون، من غير حاجة إلى ذكر خالقهم بعد وضوح أنه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص342–360.","url":""}]},{"id":"s7-1426","number":1426,"surah":7,"verses":[191],"verseLabel":"الأعراف: 191","question":"ما دلالة مقابلة ﴿لا يخلق﴾ بـ﴿وهم يُخلقون﴾؟","answer":"تقيم مقابلة قاطعة بين العجز عن خلق أي شيء والافتقار إلى من يخلقهم؛ فمن كان مخلوقًا عاجزًا لا يستحق العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص342–360.","url":""}]},{"id":"s7-1427","number":1427,"surah":7,"verses":[192],"verseLabel":"الأعراف: 192","question":"ما الفرق بين ﴿ولا يستطيعون لهم نصرًا﴾ و«ولا ينصرونهم»؟","answer":"نفي الاستطاعة ينفي أصل القدرة على النصر قبل وقوعه، فهو أبلغ من نفي فعل النصر وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص342–360.","url":""}]},{"id":"s7-1428","number":1428,"surah":7,"verses":[192],"verseLabel":"الأعراف: 192","question":"ما دلالة تقديم ﴿لهم﴾ على ﴿نصرًا﴾؟","answer":"يقدم العابدين موضع العناية؛ فالأصنام لا تملك لهم خصوصًا أدنى نصر، مع أنهم اتخذوها طلبًا لذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص342–360.","url":""}]},{"id":"s7-1429","number":1429,"surah":7,"verses":[192],"verseLabel":"الأعراف: 192","question":"ما دلالة تنكير ﴿نصرًا﴾؟","answer":"التنكير في سياق النفي يعم كل نوع وكل قدر من النصر؛ فلا يستطيعون نصرًا قليلًا ولا كثيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص342–360.","url":""}]},{"id":"s7-1430","number":1430,"surah":7,"verses":[192],"verseLabel":"الأعراف: 192","question":"ما دلالة الانتقال إلى ﴿ولا أنفسهم ينصرون﴾؟","answer":"ترقٍ في بيان العجز: من لا يستطيع حماية نفسه من الكسر والإهانة أعجز عن حماية عابديه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص342–360.","url":""}]},{"id":"s7-1431","number":1431,"surah":7,"verses":[192],"verseLabel":"الأعراف: 192","question":"ما دلالة تقديم ﴿أنفسهم﴾ في ﴿ولا أنفسهم ينصرون﴾؟","answer":"للتخصيص والعناية بأشد مواضع العجز: لا يملكون النصر حتى لأنفسهم، فضلًا عن غيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص342–360.","url":""}]},{"id":"s7-1432","number":1432,"surah":7,"verses":[193],"verseLabel":"الأعراف: 193","question":"ما دلالة الشرط في ﴿وإن تدعوهم إلى الهدى لا يتبعوكم﴾؟","answer":"يقرر عجز الأصنام في كل حال؛ فحتى لو دعاها عابدوها إلى طريق تهتدي إليه لم تسمع ولم تتبع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص342–360.","url":""}]},{"id":"s7-1433","number":1433,"surah":7,"verses":[193],"verseLabel":"الأعراف: 193","question":"ما الفرق بين تعدية الدعوة بـ﴿إلى﴾ وتعدية الاتباع بنفسه؟","answer":"الدعوة تتجه إلى غاية هي الهدى، فناسبتها ﴿إلى﴾؛ أما الاتباع فهو اقتفاء الداعي نفسه، فتعدى إلى ضميره مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص342–360.","url":""}]},{"id":"s7-1434","number":1434,"surah":7,"verses":[193],"verseLabel":"الأعراف: 193","question":"ما دلالة ﴿سواء عليكم أدعوتموهم أم أنتم صامتون﴾؟","answer":"يستوي دعاؤهم الأصنام وسكوتهم عنها؛ لأنها لا تسمع ولا تستجيب في الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص342–360.","url":""}]},{"id":"s7-1435","number":1435,"surah":7,"verses":[193],"verseLabel":"الأعراف: 193","question":"ما سرّ مجيء الطرف الأول فعلًا ﴿أدعوتموهم﴾ والثاني اسمًا ﴿أنتم صامتون﴾؟","answer":"الدعاء فعل متجدد قد يقع وقد يترك، أما الصمت فصُور حالة ثابتة؛ ومع اختلاف الصورتين فالنتيجة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص342–360.","url":""}]},{"id":"s7-1436","number":1436,"surah":7,"verses":[193],"verseLabel":"الأعراف: 193","question":"ما دلالة ﴿صامتون﴾ بدل «ساكتون»؟","answer":"الصمت إمساك عن النطق مع معنى الانغلاق، فناسب مقابلة الدعاء وإظهار أن عدم صدور صوتهم لا يغير حال الأصنام.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص342–360.","url":""}]},{"id":"s7-1437","number":1437,"surah":7,"verses":[194],"verseLabel":"الأعراف: 194","question":"ما دلالة تسمية ما يُدعى من دون الله ﴿عبادًا أمثالكم﴾؟","answer":"كل ما سوى الله مملوك مربوب خاضع له، فسماهم عبادًا لإسقاط دعوى ألوهيتهم، سواء كانوا أصنامًا أو من عُبد من العقلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص361–370.","url":""}]},{"id":"s7-1438","number":1438,"surah":7,"verses":[194],"verseLabel":"الأعراف: 194","question":"ما المقصود بقوله تعالى: ﴿أمثالكم﴾؟","answer":"المماثلة في العبودية لله والافتقار إليه، لا في جميع الصفات؛ بل أنتم أكمل من الأصنام بما أوتيتم من حياة وإدراك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص361–370.","url":""}]},{"id":"s7-1439","number":1439,"surah":7,"verses":[194],"verseLabel":"الأعراف: 194","question":"ما دلالة توالي الأمرين في ﴿فادعوهم فليستجيبوا لكم﴾؟","answer":"الأول تحدٍّ للعابدين أن يدعوا معبوداتهم، والثاني أمر تعجيزي للمعبودات أن تستجيب؛ فتظهر استحالة الدعاء وجوابه معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص361–370.","url":""}]},{"id":"s7-1440","number":1440,"surah":7,"verses":[194],"verseLabel":"الأعراف: 194","question":"ما دلالة لام الأمر في ﴿فليستجيبوا﴾؟","answer":"هي للأمر التعجيزي التهكمي؛ إذ طُلب منها ما لا قدرة لها عليه ليظهر بطلان عبادتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص361–370.","url":""}]},{"id":"s7-1441","number":1441,"surah":7,"verses":[194],"verseLabel":"الأعراف: 194","question":"ما دلالة تقديم ﴿لكم﴾ في ﴿فليستجيبوا لكم إن كنتم صادقين﴾؟","answer":"يخص العابدين بالعناية التهكمية: فلتقع الاستجابة لكم أنتم الذين تزعمون قربهم ونفعهم، إن صدق زعمكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص361–370.","url":""}]},{"id":"s7-1442","number":1442,"surah":7,"verses":[194],"verseLabel":"الأعراف: 194","question":"ما دلالة الشرط في ﴿إن كنتم صادقين﴾؟","answer":"يعلق صدق دعواهم ألوهية المعبودات على استجابتها، وهي عاجزة عنها؛ فيثبت كذب الدعوى بطريق التحدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص361–370.","url":""}]},{"id":"s7-1443","number":1443,"surah":7,"verses":[195],"verseLabel":"الأعراف: 195","question":"ما مناسبة تفصيل الجوارح بعد التحدي العام؟","answer":"فصّل وجوه عجز الأصنام في الحركة والعمل والإبصار والسماع؛ لتقوم الحجة المحسوسة على أنها دون عابديها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص371–381.","url":""}]},{"id":"s7-1444","number":1444,"surah":7,"verses":[195],"verseLabel":"الأعراف: 195","question":"ما دلالة تكرار الاستفهام في تعداد الجوارح؟","answer":"يجعل كل جارحة موضع إنكار مستقل، ويقرر العجز وجهًا بعد وجه حتى لا يبقى لمعبوداتهم وصف كمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص371–381.","url":""}]},{"id":"s7-1445","number":1445,"surah":7,"verses":[195],"verseLabel":"الأعراف: 195","question":"ما دلالة ﴿أم﴾ بين أسئلة الجوارح؟","answer":"هي منقطعة بمعنى بل والهمزة، تنتقل من إنكار إلى إنكار جديد، لا لمجرد جمع الصفات بالواو.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص371–381.","url":""}]},{"id":"s7-1446","number":1446,"surah":7,"verses":[195],"verseLabel":"الأعراف: 195","question":"ما سرّ تقديم الأرجل على الأيدي؟","answer":"بدأ بآلة الانتقال التي توصل إلى المقصود، ثم آلة البطش والعمل به؛ فجرى الترتيب على تسلسل الحركة والفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص371–381.","url":""}]},{"id":"s7-1447","number":1447,"surah":7,"verses":[195],"verseLabel":"الأعراف: 195","question":"ما دلالة قوله تعالى: ﴿أرجل يمشون بها﴾ مع أن للأصنام صور أرجل؟","answer":"العبرة بوظيفة الجارحة لا بصورتها؛ فلها أرجل مصورة لا تمشي بها، فظهرت مفارقة الاسم للحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص371–381.","url":""}]},{"id":"s7-1448","number":1448,"surah":7,"verses":[195],"verseLabel":"الأعراف: 195","question":"ما دلالة اختيار ﴿يبطشون﴾ للأيدي؟","answer":"البطش هو الأخذ والعمل بقوة، وهو أنسب بمقام التحدي والتهديد من مطلق العمل؛ فإذا عجزت عنه بطلت رهبتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص371–381.","url":""}]},{"id":"s7-1449","number":1449,"surah":7,"verses":[195],"verseLabel":"الأعراف: 195","question":"ما سرّ تأخير الأعين والآذان عن الأرجل والأيدي؟","answer":"قدم جوارح الحركة والتأثير الخارجي، ثم جوارح الإدراك التي تهدي إلى الحركة؛ فاستوعب العجز عن الفعل والإدراك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص371–381.","url":""}]},{"id":"s7-1450","number":1450,"surah":7,"verses":[195],"verseLabel":"الأعراف: 195","question":"ما مناسبة تقديم الأعين على الآذان في هذا الموضع؟","answer":"المقام في أصنام مرئية لها هيئات وأعين مصورة، فبدأ بما يشاهده المخاطب فيها، ثم أتبع السمع؛ أما آية 179 فبدأت بالقلب لأنها في تعطيل الفقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص371–381.","url":""}]},{"id":"s7-1451","number":1451,"surah":7,"verses":[195],"verseLabel":"الأعراف: 195","question":"ما سرّ استعمال ضمائر العقلاء في ﴿يمشون... يبطشون... يبصرون... يسمعون﴾؟","answer":"جرى الخطاب على زعم المشركين الذين نزّلوا الأصنام منزلة العقلاء، وفي ذلك تهكم؛ لأنها لا تؤدي شيئًا من أفعالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص371–381.","url":""}]},{"id":"s7-1452","number":1452,"surah":7,"verses":[195],"verseLabel":"الأعراف: 195","question":"ما دلالة الباء في ﴿يمشون بها... يبطشون بها... يبصرون بها... يسمعون بها﴾؟","answer":"الباء للآلة والاستعانة، فتختبر وجود الجارحة بوظيفتها التي تُستعمل بها؛ وهذه الوظائف كلها منتفية عن الأصنام.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص371–381.","url":""}]},{"id":"s7-1453","number":1453,"surah":7,"verses":[195],"verseLabel":"الأعراف: 195","question":"ما دلالة الأمر في ﴿قل ادعوا شركاءكم﴾ بعد ثبوت عجزهم؟","answer":"أمر تعجيزي يبالغ في إظهار الثقة بالله: استنصروا بكل من تزعمونهم شركاء وحاولوا الكيد مجتمعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص371–381.","url":""}]},{"id":"s7-1454","number":1454,"surah":7,"verses":[195],"verseLabel":"الأعراف: 195","question":"ما دلالة إضافة الشركاء إليهم في ﴿شركاءكم﴾؟","answer":"نسبتهم إليهم تكشف أنهم شركاء في زعم المشركين وحدهم، لا شركاء لله في الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص371–381.","url":""}]},{"id":"s7-1455","number":1455,"surah":7,"verses":[195],"verseLabel":"الأعراف: 195","question":"ما دلالة ﴿ثم﴾ في ﴿ثم كيدون﴾؟","answer":"تفيد التراخي الرتبي: بعد دعوة الشركاء والاستمداد بهم انتقلوا إلى ما هو أشد في زعمهم، وهو اجتماعهم على الكيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص371–381.","url":""}]},{"id":"s7-1456","number":1456,"surah":7,"verses":[195],"verseLabel":"الأعراف: 195","question":"ما سرّ حذف ياء المتكلم في ﴿كيدون﴾؟","answer":"حُذفت تخفيفًا واكتفاء بالكسرة الدالة عليها، ووافقت الفاصلة الموجزة الحازمة في مقام التحدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص371–381.","url":""}]},{"id":"s7-1457","number":1457,"surah":7,"verses":[195],"verseLabel":"الأعراف: 195","question":"ما دلالة قوله تعالى: ﴿فلا تنظرون﴾؟","answer":"أي لا تمهلوني لحظة، وهو غاية في التحدي وعدم المبالاة بهم وبشركائهم؛ لليقين بعجزهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص371–381.","url":""}]},{"id":"s7-1458","number":1458,"surah":7,"verses":[196],"verseLabel":"الأعراف: 196","question":"ما مناسبة تعليل التحدي بقوله تعالى: ﴿إن وليي الله﴾؟","answer":"لا يبالي بكيدهم لأن ناصره وحافظه هو الله؛ فمن كان في ولايته لم يضره تألب المعبودات العاجزة وعابديها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص382–393.","url":""}]},{"id":"s7-1459","number":1459,"surah":7,"verses":[196],"verseLabel":"الأعراف: 196","question":"ما دلالة قوله تعالى: ﴿إن وليي الله﴾ بإضافة الولي وإظهار اسم الجلالة؟","answer":"إضافة ﴿ولي﴾ إلى ياء المتكلم تشرف النبي بخصوص الولاية، وإظهار اسم الله يصرح بمنفرد الولاية والنصر ويزيد الثقة به.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص382–393.","url":""}]},{"id":"s7-1460","number":1460,"surah":7,"verses":[196],"verseLabel":"الأعراف: 196","question":"ما مناسبة وصف الله بـ﴿الولي﴾ بعد تحدي الشركاء؟","answer":"قابل أولياءهم المزعومين العاجزين بالولي الحق الذي يتولى الحفظ والنصر والتدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص382–393.","url":""}]},{"id":"s7-1461","number":1461,"surah":7,"verses":[196],"verseLabel":"الأعراف: 196","question":"ما مناسبة وصف الله بقوله: ﴿الذي نزل الكتاب﴾ في مقام الحماية؟","answer":"من أنزل على رسوله الكتاب واصطفاه لتبليغه لا يتركه لكيد أعدائه، والكتاب نفسه ناطق بولايته ونصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص382–393.","url":""}]},{"id":"s7-1462","number":1462,"surah":7,"verses":[196],"verseLabel":"الأعراف: 196","question":"ما دلالة التشديد في ﴿نزّل الكتاب﴾؟","answer":"يدل على التنزيل المفرق المتتابع بحسب الوقائع، وفي كل تنزيل تجدد للعناية والتثبيت والنصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص382–393.","url":""}]},{"id":"s7-1463","number":1463,"surah":7,"verses":[196],"verseLabel":"الأعراف: 196","question":"ما دلالة تعريف ﴿الكتاب﴾؟","answer":"للعهد؛ أي القرآن المعروف المنزل على النبي، وفي التعريف تعظيم له بوصفه الكتاب الكامل الحاضر في مقام الاحتجاج.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص382–393.","url":""}]},{"id":"s7-1464","number":1464,"surah":7,"verses":[196],"verseLabel":"الأعراف: 196","question":"ما سرّ الانتقال من ﴿وليي﴾ إلى ﴿وهو يتولى الصالحين﴾؟","answer":"عمم بعد الخصوص؛ فولاية الله ليست للنبي وحده، بل سنته أن ينصر عباده الصالحين ويحفظهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص382–393.","url":""}]},{"id":"s7-1465","number":1465,"surah":7,"verses":[196],"verseLabel":"الأعراف: 196","question":"ما دلالة المضارع في ﴿يتولى الصالحين﴾؟","answer":"يدل على تجدد ولايته واستمرارها؛ فهو يعين الصالحين وينصرهم في شؤونهم كلما تجددت حاجتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص382–393.","url":""}]},{"id":"s7-1466","number":1466,"surah":7,"verses":[196],"verseLabel":"الأعراف: 196","question":"ما دلالة وصف أولياء الله بـ﴿الصالحين﴾؟","answer":"الصلاح سلامة الباطن بالإخلاص وظهور أثره في العمل النافع؛ وهو الوصف الذي يؤهل صاحبه للولاية والنصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص382–393.","url":""}]},{"id":"s7-1467","number":1467,"surah":7,"verses":[197],"verseLabel":"الأعراف: 197","question":"ما فائدة إعادة عجز المعبودات عن النصر بعد ذكره في الآية 192؟","answer":"أعيد بعد تقرير ولاية الله لتكتمل المقابلة: الله يتولى الصالحين، أما ما يدعونه فلا ينصر عابديه ولا نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص394–403.","url":""}]},{"id":"s7-1468","number":1468,"surah":7,"verses":[197],"verseLabel":"الأعراف: 197","question":"ما سرّ التعبير هنا بـ﴿من دونه﴾ وقبلها بـ﴿من دون الله﴾؟","answer":"ذُكر اسم الله قبلها مباشرة في ﴿إن وليي الله﴾، فحسن عود الضمير إليه، أما الموضع السابق فاحتاج إلى التصريح ابتداءً.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص394–403.","url":""}]},{"id":"s7-1469","number":1469,"surah":7,"verses":[197],"verseLabel":"الأعراف: 197","question":"ما دلالة إعادة ﴿الذين تدعون﴾ بدل الاكتفاء بالضمير؟","answer":"يعيد وصفهم بالفعل الذي قامت عليه الحجة؛ فكونهم مدعوين من دون الله هو موضع الإنكار وسبب الحكم بعجزهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص394–403.","url":""}]},{"id":"s7-1470","number":1470,"surah":7,"verses":[197],"verseLabel":"الأعراف: 197","question":"ما الفرق بين ﴿لا يستطيعون نصركم﴾ و﴿لا يستطيعون لهم نصرًا﴾ في الآية 192؟","answer":"الأولى واجهت العابدين مباشرة بعد تحديهم فناسب ﴿نصركم﴾، أما السابقة فكانت في حكاية حالهم بضمير الغيبة ونكّرت النصر لاستغراق أنواعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص394–403.","url":""}]},{"id":"s7-1471","number":1471,"surah":7,"verses":[197],"verseLabel":"الأعراف: 197","question":"ما سرّ تقديم عجزهم عن نصر العابدين على عجزهم عن نصر أنفسهم؟","answer":"بدأ بإبطال الغرض الذي عبدوهم لأجله، وهو طلب نصرهم، ثم ذكر الدليل الأقوى عليه: عجزهم عن نصر أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص394–403.","url":""}]},{"id":"s7-1472","number":1472,"surah":7,"verses":[197],"verseLabel":"الأعراف: 197","question":"ما دلالة تقديم ﴿أنفسهم﴾ في ﴿ولا أنفسهم ينصرون﴾؟","answer":"يبرز موضع العجز الأشد: لا يقدرون على دفع الأذى عن ذواتهم التي هي أولى بالنصر، فغيرهم أعجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص394–403.","url":""}]},{"id":"s7-1473","number":1473,"surah":7,"verses":[198],"verseLabel":"الأعراف: 198","question":"ما فائدة إعادة ﴿وإن تدعوهم إلى الهدى﴾ بعد الآية 193؟","answer":"أعيد لتقرير وجه آخر من العجز: سبق نفي اتباعهم للداعي، وهنا نُفي أصل سماعهم، ثم أضيف نفي إبصارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص404–414.","url":""}]},{"id":"s7-1474","number":1474,"surah":7,"verses":[198],"verseLabel":"الأعراف: 198","question":"ما الفرق بين ﴿لا يسمعوا﴾ هنا و﴿لا يتبعوكم﴾ في الآية 193؟","answer":"نفي السماع يثبت فقد أداة تلقي الدعوة، ونفي الاتباع يثبت فقد الاستجابة لها؛ فالثاني نتيجة ممتنعة لأن الأول غير موجود أصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص404–414.","url":""}]},{"id":"s7-1475","number":1475,"surah":7,"verses":[198],"verseLabel":"الأعراف: 198","question":"ما الصورة في قوله تعالى: ﴿وتراهم ينظرون إليك وهم لا يبصرون﴾؟","answer":"تبدو الأصنام بعيونها المصورة كأنها تنظر إلى الناظر، ثم تكشف الحال أنها لا تبصر شيئًا؛ فالمشهد يهدم خداع الصورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص404–414.","url":""}]},{"id":"s7-1476","number":1476,"surah":7,"verses":[198],"verseLabel":"الأعراف: 198","question":"ما وجه إسناد النظر إلى الأصنام؟","answer":"أُسند إليها بحسب هيئة أعينها المقابلة للناظر، لا على الحقيقة؛ ولذلك أتبع بنفي الإبصار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص404–414.","url":""}]},{"id":"s7-1477","number":1477,"surah":7,"verses":[198],"verseLabel":"الأعراف: 198","question":"ما دلالة تعدية النظر بـ﴿إلى﴾؟","answer":"تفيد توجيه العين نحو المرئي، وهو القدر الظاهري الذي توهمه هيئة الأصنام، من غير تحقق الرؤية والإدراك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص404–414.","url":""}]},{"id":"s7-1478","number":1478,"surah":7,"verses":[198],"verseLabel":"الأعراف: 198","question":"ما سرّ نفي الإبصار بعد إثبات النظر؟","answer":"النظر توجيه العين وقد يوجد بلا رؤية، أما الإبصار فهو حصول الإدراك؛ فأثبت هيئة النظر ونفى غايته وحقيقته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص404–414.","url":""}]},{"id":"s7-1479","number":1479,"surah":7,"verses":[198],"verseLabel":"الأعراف: 198","question":"ما دلالة مجيء ﴿وهم لا يبصرون﴾ جملة حالية؟","answer":"تكشف حالهم في اللحظة التي يوهم ظاهرها النظر: تراهم متجهين إليك، والحقيقة المقارنة لذلك أنهم لا يبصرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص404–414.","url":""}]},{"id":"s7-1480","number":1480,"surah":7,"verses":[199],"verseLabel":"الأعراف: 199","question":"ما مناسبة افتتاح الوصايا الجامعة بـ﴿خذ العفو﴾؟","answer":"بدأ بإصلاح معاملة الداعي للناس: يقبل ما سهل من أخلاقهم ولا يستقصي حقوقه، فيتهيأ بعد ذلك للأمر بالخير واحتمال الجاهلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص415–430.","url":""}]},{"id":"s7-1481","number":1481,"surah":7,"verses":[199],"verseLabel":"الأعراف: 199","question":"ما المراد بـ﴿العفو﴾ في قوله تعالى: ﴿خذ العفو﴾؟","answer":"هو ما سهل وتيسر من أخلاق الناس وأعمالهم من غير استقصاء، ويتضمن المسامحة وترك المؤاخذة؛ وهذه المعاني متقاربة وليست متعارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص415–430.","url":""}]},{"id":"s7-1482","number":1482,"surah":7,"verses":[199],"verseLabel":"الأعراف: 199","question":"ما دلالة ﴿خذ﴾ بدل «اقبل»؟","answer":"الأخذ يدل على مباشرة هذا الخلق والتمسك به وجعله منهجًا ثابتًا، وهو أقوى من مجرد القبول النفسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص415–430.","url":""}]},{"id":"s7-1483","number":1483,"surah":7,"verses":[199],"verseLabel":"الأعراف: 199","question":"ما دلالة التعبير بـ﴿العرف﴾ بدل «المعروف»؟","answer":"العرف هو الأمر الظاهر الحسن الذي تعرفه العقول السليمة وتطمئن إليه النفوس، فهو أبلغ في استحضار ظهور الخير واستقراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص415–430.","url":""}]},{"id":"s7-1484","number":1484,"surah":7,"verses":[199],"verseLabel":"الأعراف: 199","question":"ما دلالة تعريف ﴿العرف﴾؟","answer":"يستغرق جنس الخير المعروف الموافق للشرع والفطرة السليمة، لا خصلة واحدة بعينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص415–430.","url":""}]},{"id":"s7-1485","number":1485,"surah":7,"verses":[199],"verseLabel":"الأعراف: 199","question":"ما سرّ ترتيب العفو ثم الأمر بالعرف ثم الإعراض عن الجاهلين؟","answer":"بدأ بتهذيب معاملة النفس، ثم انتقل إلى إصلاح الناس بالأمر بالخير، ثم بيّن ما يحفظ الداعي من سفه من لا يستجيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص415–430.","url":""}]},{"id":"s7-1486","number":1486,"surah":7,"verses":[199],"verseLabel":"الأعراف: 199","question":"ما دلالة الأمر بـ﴿وأعرض عن الجاهلين﴾ بدل مقابلتهم بالعقوبة؟","answer":"المطلوب ترك مجاراتهم في السفه وعدم الاشتغال بانتقام النفس، لا ترك بيان الحق ولا تعطيل العقوبة المشروعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص415–430.","url":""}]},{"id":"s7-1487","number":1487,"surah":7,"verses":[199],"verseLabel":"الأعراف: 199","question":"ما دلالة وصف المؤذين بـ﴿الجاهلين﴾؟","answer":"سماهم بما يكشف منشأ سفههم؛ فالجهل هنا سوء التصرف ومجاوزة الحلم، ووصفهم به يهيئ للإعراض عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص415–430.","url":""}]},{"id":"s7-1488","number":1488,"surah":7,"verses":[199],"verseLabel":"الأعراف: 199","question":"ما دلالة جمع ﴿الجاهلين﴾؟","answer":"يعم كل من صدرت منه جهالة، ويجعل الإعراض منهجًا في التعامل مع هذا الصنف لا موقفًا من فرد واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص415–430.","url":""}]},{"id":"s7-1489","number":1489,"surah":7,"verses":[199],"verseLabel":"الأعراف: 199","question":"ما وجه جمع الآية مكارم الأخلاق في ألفاظ قليلة؟","answer":"جمعت بذل السماحة في ﴿خذ العفو﴾، وإيصال الخير في ﴿وأمر بالعرف﴾، وكف الشر في ﴿وأعرض عن الجاهلين﴾؛ فاستوعبت حسن الخلق فعلًا وتركًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص415–430.","url":""}]},{"id":"s7-1490","number":1490,"surah":7,"verses":[200],"verseLabel":"الأعراف: 200","question":"ما مناسبة قوله تعالى: ﴿وإما ينزغنك من الشيطان نزغ﴾ بعد الأمر بالإعراض عن الجاهلين؟","answer":"لما كان أذى الجاهلين قد يحرك الغضب ويدعو إلى مقابلتهم، نبه إلى أن هذا النزغ من الشيطان، وبيّن علاجه بالاستعاذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص431–442.","url":""}]},{"id":"s7-1491","number":1491,"surah":7,"verses":[200],"verseLabel":"الأعراف: 200","question":"ما دلالة دخول ﴿ما﴾ على ﴿إن﴾ في ﴿وإما﴾؟","answer":"﴿ما﴾ زائدة للتوكيد، ودخولها هيأ ﴿إن﴾ الشرطية لاتصال نون التوكيد بالفعل ﴿ينزغنك﴾، فقوّى التنبيه إلى احتمال النزغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص431–442.","url":""}]},{"id":"s7-1492","number":1492,"surah":7,"verses":[200],"verseLabel":"الأعراف: 200","question":"ما دلالة ﴿ينزغنك﴾ بدل «يوسوس لك»؟","answer":"النزغ حركة سريعة مفسدة تهيج الغضب وتدفع إلى الشر، فهو أخص بالمقام وأقوى حركة من مجرد الوسوسة الخفية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص431–442.","url":""}]},{"id":"s7-1493","number":1493,"surah":7,"verses":[200],"verseLabel":"الأعراف: 200","question":"ما دلالة الجمع بين الفعل ومصدره في ﴿ينزغنك... نزغ﴾؟","answer":"المصدر فاعل للفعل، أي إن يصبك من الشيطان نزغ؛ وفي اشتقاق الفعل والفاعل من مادة واحدة تجنيس يركز معنى الحركة المفسدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص431–442.","url":""}]},{"id":"s7-1494","number":1494,"surah":7,"verses":[200],"verseLabel":"الأعراف: 200","question":"ما دلالة تقديم ﴿من الشيطان﴾ على ﴿نزغ﴾؟","answer":"يبادر بتعيين مصدر النزغ قبل تسميته، تنفيرًا منه وتنبيهًا إلى أن هذه الحركة المفسدة من الشيطان خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص431–442.","url":""}]},{"id":"s7-1495","number":1495,"surah":7,"verses":[200],"verseLabel":"الأعراف: 200","question":"ما مناسبة جواب الشرط: ﴿فاستعذ بالله﴾؟","answer":"لأن الشيطان عدو خفي لا يدفع نزغه إلا الالتجاء إلى الله القادر عليه؛ فكانت الاستعاذة العلاج المباشر عند وقوع سببه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص431–442.","url":""}]},{"id":"s7-1496","number":1496,"surah":7,"verses":[200],"verseLabel":"الأعراف: 200","question":"ما دلالة اختيار الاستعاذة بدل مجرد الذكر؟","answer":"الاستعاذة تفيد الالتجاء والاحتماء بالقوي، وتظهر ضعف العبد وانكساره وتبرؤه من حوله وقوته؛ فهي أخص بدفع النزغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص431–442.","url":""}]},{"id":"s7-1497","number":1497,"surah":7,"verses":[200],"verseLabel":"الأعراف: 200","question":"ما سرّ إظهار اسم الله في ﴿فاستعذ بالله﴾؟","answer":"دفع الإضمار لبس عود الضمير إلى الشيطان، واستحضر اسم الجلالة الجامع لمعاني الكمال والمهابة في مقام الاحتماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص431–442.","url":""}]},{"id":"s7-1498","number":1498,"surah":7,"verses":[200],"verseLabel":"الأعراف: 200","question":"ما مناسبة ختم الآية بـ﴿إنه سميع عليم﴾؟","answer":"تعليل للأمر بالاستعاذة: الله يسمع التجاء المستعيذ ويعلم نزغ الشيطان وحال من احتمى به، فيكفيه ويحميه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص431–442.","url":""}]},{"id":"s7-1499","number":1499,"surah":7,"verses":[200],"verseLabel":"الأعراف: 200","question":"ما سرّ تقديم ﴿سميع﴾ على ﴿عليم﴾؟","answer":"لأن المقام مقام استعاذة ودعاء ملفوظ، فناسب تقديم سماع القول، ثم عمم بالعلم المحيط بالسر والحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص431–442.","url":""}]},{"id":"s7-1500","number":1500,"surah":7,"verses":[201],"verseLabel":"الأعراف: 201","question":"ما مناسبة قوله تعالى: ﴿إن الذين اتقوا﴾ بعد أمر النبي ﷺ بالاستعاذة؟","answer":"عمم العلاج بعد توجيهه إلى النبي؛ فشأن المتقين جميعًا أنهم إذا مسهم الشيطان رجعوا إلى الله، والتقوى وقاية من تمكنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص443–458.","url":""}]},{"id":"s7-1501","number":1501,"surah":7,"verses":[201],"verseLabel":"الأعراف: 201","question":"ما دلالة ﴿مسهم﴾ بدل «أصابهم»؟","answer":"المس أخف الإصابة، فيدل على أن وسوسة الشيطان لا تتمكن من المتقين، بل تلامسهم عارضة ثم تزول بالتذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص443–458.","url":""}]},{"id":"s7-1502","number":1502,"surah":7,"verses":[200,201],"verseLabel":"الأعراف: 200–201","question":"ما الفرق بين ﴿نزغ من الشيطان﴾ و﴿طائف من الشيطان﴾؟","answer":"النزغ حركة مفسدة تهيج إلى الشر، والطائف خاطر أو وسوسة تطوف بالقلب ولا تستقر؛ فالأول يصور الدفع، والثاني سرعة المرور.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص443–458.","url":""}]},{"id":"s7-1503","number":1503,"surah":7,"verses":[201],"verseLabel":"الأعراف: 201","question":"ما دلالة تنكير ﴿طائف﴾؟","answer":"للتحقير والتقليل؛ فأدنى خاطر من الشيطان ينبه المتقين إلى التذكر، ولا يتمكن منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص443–458.","url":""}]},{"id":"s7-1504","number":1504,"surah":7,"verses":[201],"verseLabel":"الأعراف: 201","question":"ما دلالة إسناد المس إلى المتقين في ﴿مسهم﴾؟","answer":"يثبت إمكان تعرض المتقي للخاطر الشيطاني، لكن الإسناد مع لفظ المس يدل على إصابة عابرة لا على استقرار الغواية فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص443–458.","url":""}]},{"id":"s7-1505","number":1505,"surah":7,"verses":[201],"verseLabel":"الأعراف: 201","question":"ما مناسبة جواب مس الشيطان بقوله تعالى: ﴿تذكروا﴾؟","answer":"لأن الغفلة منفذ الشيطان، فإذا تذكروا أمر الله ونهيه وثوابه وعقابه انكشف الخاطر وانقطع أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص443–458.","url":""}]},{"id":"s7-1506","number":1506,"surah":7,"verses":[201],"verseLabel":"الأعراف: 201","question":"ما دلالة حذف مفعول ﴿تذكروا﴾؟","answer":"لإفادة العموم؛ تذكروا ما يردعهم من أمر الله ومراقبته ووعده ووعيده، فلا يحصر التذكر في شيء واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص443–458.","url":""}]},{"id":"s7-1507","number":1507,"surah":7,"verses":[201],"verseLabel":"الأعراف: 201","question":"ما دلالة المفاجأة في ﴿فإذا هم مبصرون﴾؟","answer":"تصور سرعة انكشاف وسوسة الشيطان عقب التذكر؛ فما إن يتذكروا حتى تعود بصيرتهم فورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص443–458.","url":""}]},{"id":"s7-1508","number":1508,"surah":7,"verses":[201],"verseLabel":"الأعراف: 201","question":"ما دلالة ﴿مبصرون﴾ بدل «يعلمون»؟","answer":"يصور الحق بعد التذكر كأنه مشهد واضح تراه البصيرة، لا مجرد معلومة ذهنية؛ فيميزون طريق الرشد من الغي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص443–458.","url":""}]},{"id":"s7-1509","number":1509,"surah":7,"verses":[201],"verseLabel":"الأعراف: 201","question":"ما دلالة الجملة الاسمية في ﴿هم مبصرون﴾؟","answer":"تفيد تحقق الإبصار وثباته فيهم عقب التذكر، وجاء الضمير لزيادة تقرير حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص443–458.","url":""}]},{"id":"s7-1510","number":1510,"surah":7,"verses":[202],"verseLabel":"الأعراف: 202","question":"من المراد بـ﴿إخوانهم﴾، وإلى من يعود الضمير؟","answer":"المراد إخوان الشياطين من الغاوين والمشركين، والضمير يعود إلى الشيطان باعتبار جنسه؛ فشياطين الجن تمد أولياءها من الإنس في الغي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص459–469.","url":""}]},{"id":"s7-1511","number":1511,"surah":7,"verses":[202],"verseLabel":"الأعراف: 202","question":"ما دلالة تسميتهم ﴿إخوانهم﴾؟","answer":"الأخوة هنا أخوة الموالاة والموافقة في الغي؛ فهي تصور قوة الصلة بين الشياطين ومن يستجيبون لإغوائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص459–469.","url":""}]},{"id":"s7-1512","number":1512,"surah":7,"verses":[202],"verseLabel":"الأعراف: 202","question":"ما دلالة ﴿يمدونهم﴾ بدل «يضلونهم»؟","answer":"المد يدل على الإطالة والزيادة والاستمرار؛ فالشياطين لا تبدأ الغي فحسب، بل تزيد أولياءها فيه وتمده لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص459–469.","url":""}]},{"id":"s7-1513","number":1513,"surah":7,"verses":[202],"verseLabel":"الأعراف: 202","question":"ما الصورة في قوله تعالى: ﴿يمدونهم في الغي﴾؟","answer":"صُور الغي مكانًا عميقًا يتغلغلون فيه، والشياطين تطيل لهم حبل الضلال حتى يزدادوا بعدًا ولا يفلتوا منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص459–469.","url":""}]},{"id":"s7-1514","number":1514,"surah":7,"verses":[202],"verseLabel":"الأعراف: 202","question":"ما دلالة ﴿ثم﴾ في ﴿ثم لا يقصرون﴾؟","answer":"تفيد التراخي الرتبي؛ فبعد إمدادهم في الغي يبلغ الأمر رتبة أشد، وهي استمرارهم فيه من غير كف ولا فتور.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص459–469.","url":""}]},{"id":"s7-1515","number":1515,"surah":7,"verses":[202],"verseLabel":"الأعراف: 202","question":"إلى من يعود فاعل ﴿لا يقصرون﴾؟","answer":"يعود في المعنى الأول إلى الشياطين؛ فلا يكفون عن إمداد إخوانهم في الغي، ويحتمل الغاوين أيضًا؛ فلا يكفون عن قبول الإغواء والتمادي فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص459–469.","url":""}]},{"id":"s7-1516","number":1516,"surah":7,"verses":[202],"verseLabel":"الأعراف: 202","question":"ما دلالة المضارع المنفي في ﴿لا يقصرون﴾؟","answer":"يدل على تجدد عدم الكف واستمراره؛ فالإمداد بالغي والتمادي فيه ديدن متواصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص459–469.","url":""}]},{"id":"s7-1517","number":1517,"surah":7,"verses":[203],"verseLabel":"الأعراف: 203","question":"ما المراد بقوله تعالى: ﴿وإذا لم تأتهم بآية﴾ مع توالي آيات القرآن؟","answer":"المراد آية يقترحونها أو وحي جديد يوافق أهواءهم، لا انتفاء آيات القرآن الموجودة؛ فقد كانوا يطلبون من الرسول اختراع الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص470–487.","url":""}]},{"id":"s7-1518","number":1518,"surah":7,"verses":[203],"verseLabel":"الأعراف: 203","question":"ما دلالة استعمال ﴿إذا﴾ في ﴿وإذا لم تأتهم بآية﴾؟","answer":"لأن عدم مجيء الرسول بكل آية يقترحونها أمر متحقق متكرر، فناسبته ﴿إذا﴾ الدالة على تحقق الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص470–487.","url":""}]},{"id":"s7-1519","number":1519,"surah":7,"verses":[203],"verseLabel":"الأعراف: 203","question":"ما معنى قولهم: ﴿لولا اجتبيتها﴾؟","answer":"أي هلا اخترعتها أو اخترتها وجمعتها من عند نفسك؛ وهو قول يكشف توهمهم أن الرسول يملك إنشاء الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص470–487.","url":""}]},{"id":"s7-1520","number":1520,"surah":7,"verses":[203],"verseLabel":"الأعراف: 203","question":"ما دلالة اختيار ﴿اجتبيتها﴾ بدل «أتيت بها»؟","answer":"الاجتباء يتضمن الاختيار والجمع والاصطفاء، فيصور باطل ظنهم أن النبي ينتقي الآية من عنده، لا أنه مجرد يأتي بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص470–487.","url":""}]},{"id":"s7-1521","number":1521,"surah":7,"verses":[203],"verseLabel":"الأعراف: 203","question":"ما دلالة القصر في ﴿إنما أتبع ما يوحى إلي﴾؟","answer":"يقصر شأن الرسول على اتباع الوحي، وينفي أن يخترع آية أو يغيرها استجابة لاقتراحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص470–487.","url":""}]},{"id":"s7-1522","number":1522,"surah":7,"verses":[203],"verseLabel":"الأعراف: 203","question":"ما دلالة المضارع في ﴿أتبع﴾ و﴿يوحى﴾؟","answer":"يدل على تجدد نزول الوحي وتجدد اتباع الرسول له؛ فكلما أوحي إليه شيء بلغه واتّبعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص470–487.","url":""}]},{"id":"s7-1523","number":1523,"surah":7,"verses":[203],"verseLabel":"الأعراف: 203","question":"ما دلالة بناء ﴿يوحى﴾ للمجهول؟","answer":"يوجه العناية إلى حقيقة الوحي الذي يتبعه الرسول لا إلى ذكر فاعله، وقد عُلم من قوله بعدها: ﴿من ربي﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص470–487.","url":""}]},{"id":"s7-1524","number":1524,"surah":7,"verses":[203],"verseLabel":"الأعراف: 203","question":"ما دلالة قوله تعالى: ﴿إلي من ربي﴾؟","answer":"﴿إلي﴾ تثبت أن الرسول متلقٍ لا منشئ، و﴿من ربي﴾ تعين مصدر الوحي وتستحضر التربية والرعاية بالتنزيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص470–487.","url":""}]},{"id":"s7-1525","number":1525,"surah":7,"verses":[203],"verseLabel":"الأعراف: 203","question":"ما دلالة الإشارة إلى القرآن في ﴿هذا بصائر﴾؟","answer":"تشير إلى القرآن الحاضر المتلو، وتواجه اقتراحهم بآية أخرى بأن بين أيديهم آيات واضحة تكفي من طلب الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص470–487.","url":""}]},{"id":"s7-1526","number":1526,"surah":7,"verses":[203],"verseLabel":"الأعراف: 203","question":"ما سرّ جمع ﴿بصائر﴾ مع الإشارة إلى القرآن المفرد؟","answer":"القرآن واحد، لكن آياته ودلائله المتعددة كل واحدة منها بصيرة تكشف وجهًا من الحق؛ فجمع آثار أجزائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص470–487.","url":""}]},{"id":"s7-1527","number":1527,"surah":7,"verses":[203],"verseLabel":"الأعراف: 203","question":"ما دلالة تسمية القرآن ﴿بصائر﴾ بدل «أبصارًا»؟","answer":"البصائر نور القلب الذي يدرك به الحق، أما الأبصار فحاسة العين؛ والقرآن يكشف المعاني والهداية للبصائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص470–487.","url":""}]},{"id":"s7-1528","number":1528,"surah":7,"verses":[203],"verseLabel":"الأعراف: 203","question":"ما سرّ الانتقال من ﴿من ربي﴾ إلى ﴿من ربكم﴾؟","answer":"الأول يبين مصدر ما يتلقاه الرسول، والثاني يواجه المخاطبين بأن القرآن عناية من ربهم هم، أقام بها حجتهم وهدايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص470–487.","url":""}]},{"id":"s7-1529","number":1529,"surah":7,"verses":[203],"verseLabel":"الأعراف: 203","question":"ما دلالة الجمع بين ﴿بصائر وهدى ورحمة﴾؟","answer":"البصائر تكشف الحق، والهدى يقود إلى طريقه، والرحمة ثمرة اتباعه؛ فجمعت الآية البيان والدلالة والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص470–487.","url":""}]},{"id":"s7-1530","number":1530,"surah":7,"verses":[203],"verseLabel":"الأعراف: 203","question":"ما دلالة تقييد الهدى والرحمة بـ﴿لقوم يؤمنون﴾؟","answer":"القرآن بصائر للناس، لكن المؤمنين هم الذين يقبلون دلالته فيتحقق لهم الهدى والرحمة؛ فالقيد للانتفاع لا لعموم الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص470–487.","url":""}]},{"id":"s7-1531","number":1531,"surah":7,"verses":[204],"verseLabel":"الأعراف: 204","question":"ما دلالة بناء ﴿قُرئ القرآن﴾ للمجهول؟","answer":"يعمم الحكم في كل قراءة معتبرة، ويصرف العناية من شخصية القارئ إلى القرآن المقروء وحقه في الاستماع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص488–495.","url":""}]},{"id":"s7-1532","number":1532,"surah":7,"verses":[204],"verseLabel":"الأعراف: 204","question":"ما دلالة تعريف ﴿القرآن﴾؟","answer":"للعهد والتعظيم؛ أي هذا الكتاب المعروف الجامع الذي وصف قبلها بأنه بصائر وهدى ورحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص488–495.","url":""}]},{"id":"s7-1533","number":1533,"surah":7,"verses":[204],"verseLabel":"الأعراف: 204","question":"ما الفرق بين ﴿فاستمعوا له﴾ و﴿أنصتوا﴾؟","answer":"الاستماع قصد السمع وإقبال القلب على المقروء، والإنصات ترك الكلام والشاغل؛ فجمع بين فعل التلقي وإزالة ما يمنعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص488–495.","url":""}]},{"id":"s7-1534","number":1534,"surah":7,"verses":[204],"verseLabel":"الأعراف: 204","question":"ما سرّ تقديم الاستماع على الإنصات؟","answer":"قدم الغاية المقصودة، وهي تلقي القرآن بالقصد والتدبر، ثم أمر بما يعين عليها من ترك الكلام والشواغل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص488–495.","url":""}]},{"id":"s7-1535","number":1535,"surah":7,"verses":[204],"verseLabel":"الأعراف: 204","question":"ما دلالة اللام في ﴿فاستمعوا له﴾؟","answer":"تفيد توجيه القصد والاهتمام إلى القرآن خاصة، لا مجرد وقوع صوته في الأذن.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص488–495.","url":""}]},{"id":"s7-1536","number":1536,"surah":7,"verses":[204],"verseLabel":"الأعراف: 204","question":"ما دلالة حذف متعلق ﴿أنصتوا﴾؟","answer":"ليعم الإنصات عن كل كلام وصوت وشاغل يحول دون حسن الاستماع للقرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص488–495.","url":""}]},{"id":"s7-1537","number":1537,"surah":7,"verses":[204],"verseLabel":"الأعراف: 204","question":"ما دلالة عطف الإنصات بالواو؟","answer":"يدل على أن الاستماع والإنصات مطلوبان مجتمعين، من غير جعل أحدهما نتيجة زمنية لازمة للآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص488–495.","url":""}]},{"id":"s7-1538","number":1538,"surah":7,"verses":[204],"verseLabel":"الأعراف: 204","question":"ما مناسبة ختم الآية بـ﴿لعلكم ترحمون﴾؟","answer":"جعل الرحمة ثمرة مرجوة للاستماع والإنصات؛ لأنهما طريق فهم القرآن وقبول هدايته والعمل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص488–495.","url":""}]},{"id":"s7-1539","number":1539,"surah":7,"verses":[205],"verseLabel":"الأعراف: 205","question":"ما مناسبة الأمر بذكر الله في النفس بعد الأمر بالاستماع للقرآن؟","answer":"بعد تلقي كلام الله أمر باستدامة الصلة به بالذكر؛ فالاستماع غذاء من الوحي، والذكر استجابة قلبية تحفظ أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص496–507.","url":""}]},{"id":"s7-1540","number":1540,"surah":7,"verses":[205],"verseLabel":"الأعراف: 205","question":"ما دلالة اختيار ﴿ربك﴾ في ﴿واذكر ربك﴾؟","answer":"يستحضر التربية والرعاية والإنعام، ويضيف الرب إلى النبي تشريفًا وتقريبًا يحفزه على دوام الذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص496–507.","url":""}]},{"id":"s7-1541","number":1541,"surah":7,"verses":[205],"verseLabel":"الأعراف: 205","question":"ما دلالة قوله تعالى: ﴿في نفسك﴾؟","answer":"يدل على الذكر الخفي الحاضر في القلب، البعيد عن الرياء، مع استبطان عظمة المذكور ومراقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص496–507.","url":""}]},{"id":"s7-1542","number":1542,"surah":7,"verses":[205],"verseLabel":"الأعراف: 205","question":"ما دلالة الجمع بين ﴿تضرعًا وخيفة﴾؟","answer":"التضرع إظهار الذل والافتقار، والخيفة خوف القلب؛ فجمع بين هيئة العبودية الظاهرة وحالها الباطنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص496–507.","url":""}]},{"id":"s7-1543","number":1543,"surah":7,"verses":[205],"verseLabel":"الأعراف: 205","question":"ما دلالة تنكير ﴿خيفة﴾؟","answer":"يفيد نوعًا حاضرًا من الخوف الخفي المناسب للذكر في النفس، من غير تكلف ولا تحديد لدرجة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص496–507.","url":""}]},{"id":"s7-1544","number":1544,"surah":7,"verses":[205],"verseLabel":"الأعراف: 205","question":"ما الفرق بين ﴿ودون الجهر من القول﴾ و«سرًا»؟","answer":"﴿دون الجهر﴾ يثبت قولًا مسموعًا منخفضًا بين الجهر والإسرار التام، فيجمع حضور اللسان وخشوع الصوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص496–507.","url":""}]},{"id":"s7-1545","number":1545,"surah":7,"verses":[205],"verseLabel":"الأعراف: 205","question":"ما دلالة تقييد الذكر بـ﴿بالغدو والآصال﴾؟","answer":"خُص أول النهار وآخره لأنهما طرفاه وأوقات تجدد الأحوال، وذكر الطرفين كناية عن ملازمة الذكر في اليوم كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص496–507.","url":""}]},{"id":"s7-1546","number":1546,"surah":7,"verses":[205],"verseLabel":"الأعراف: 205","question":"ما سرّ إفراد ﴿الغدو﴾ وجمع ﴿الآصال﴾؟","answer":"الغدو اسم جنس لوقت الغداة فيؤدي معنى الجمع، أما الآصال فجمع أصيل؛ فاختلف اللفظان مع دلالتهما على تكرر الطرفين كل يوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص496–507.","url":""}]},{"id":"s7-1547","number":1547,"surah":7,"verses":[205],"verseLabel":"الأعراف: 205","question":"ما مناسبة النهي في ﴿ولا تكن من الغافلين﴾؟","answer":"لما أمر بدوام الذكر نهى عن ضده، وهو الغفلة التي تقطع الصلة بالله وتفتح مدخل الشيطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص496–507.","url":""}]},{"id":"s7-1548","number":1548,"surah":7,"verses":[205],"verseLabel":"الأعراف: 205","question":"ما الفرق بين ﴿ولا تكن من الغافلين﴾ و«ولا تكن غافلًا»؟","answer":"التعبير بـ﴿من الغافلين﴾ ينهى عن أدنى انتساب إلى جماعتهم والدخول في طريقتهم، لا عن حالة غفلة مفردة فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص496–507.","url":""}]},{"id":"s7-1549","number":1549,"surah":7,"verses":[206],"verseLabel":"الأعراف: 206","question":"ما مناسبة ختم السورة بذكر ﴿الذين عند ربك﴾؟","answer":"جعل الملائكة المقربين قدوة في دوام العبادة بعد الأمر بالذكر والنهي عن الغفلة، وفيه حث على التشبه بأهل الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص508–520.","url":""}]},{"id":"s7-1550","number":1550,"surah":7,"verses":[206],"verseLabel":"الأعراف: 206","question":"من المراد بـ﴿الذين عند ربك﴾، وما دلالة العندية؟","answer":"المشهور أنهم الملائكة المقربون، والعندية عندية منزلة وزلفى ورحمة، لا قرب مكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص508–520.","url":""}]},{"id":"s7-1551","number":1551,"surah":7,"verses":[206],"verseLabel":"الأعراف: 206","question":"ما دلالة اختيار ﴿ربك﴾ في وصف قرب الملائكة؟","answer":"يستحضر رعاية الله للنبي ويشرفه بالإضافة، ويحثه على الالتحاق في الذكر بمن قربتهم طاعتهم من رحمة ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص508–520.","url":""}]},{"id":"s7-1552","number":1552,"surah":7,"verses":[206],"verseLabel":"الأعراف: 206","question":"ما مناسبة قوله تعالى: ﴿لا يستكبرون عن عبادته﴾ بعد النهي عن الغفلة؟","answer":"يعلل الحث على الذكر بحال الملائكة: علو منزلتهم لم يحملهم على ترك العبادة، فالبشر أولى باجتناب الغفلة والاستكبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص508–520.","url":""}]},{"id":"s7-1553","number":1553,"surah":7,"verses":[206],"verseLabel":"الأعراف: 206","question":"ما دلالة تعدية الاستكبار بـ﴿عن﴾؟","answer":"تصور الاستكبار انصرافًا ومجاوزةً للعبادة؛ فنفت عن الملائكة أن يحملهم علوهم على البعد عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص508–520.","url":""}]},{"id":"s7-1554","number":1554,"surah":7,"verses":[206],"verseLabel":"الأعراف: 206","question":"ما دلالة إضافة العبادة إلى ضميره في ﴿عبادته﴾؟","answer":"تخص العبادة بالله الذي ذُكر بوصف الرب، وتبرز شرفها لأنها عبادة له وحده لا لغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص508–520.","url":""}]},{"id":"s7-1555","number":1555,"surah":7,"verses":[206],"verseLabel":"الأعراف: 206","question":"ما دلالة العطف في ﴿ويسبحونه وله يسجدون﴾؟","answer":"فصّل عبادتهم بعد نفي الاستكبار: ينزهونه بأقوالهم واعتقادهم، ويخضعون له بالسجود؛ فجمع التنزيه والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص508–520.","url":""}]},{"id":"s7-1556","number":1556,"surah":7,"verses":[206],"verseLabel":"الأعراف: 206","question":"ما دلالة تقديم ﴿له﴾ على ﴿يسجدون﴾؟","answer":"يفيد الاختصاص: لله وحده يسجدون، لا يشركون به في غاية الخضوع أحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص508–520.","url":""}]},{"id":"s7-1557","number":1557,"surah":7,"verses":[206],"verseLabel":"الأعراف: 206","question":"ما سرّ تقديم التسبيح على السجود؟","answer":"بدأ بتنزيه الاعتقاد والقول، ثم أتبعه بأقصى خضوع الجوارح؛ فسلامة التصور مقدمة على العمل الناشئ عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص508–520.","url":""}]},{"id":"s7-1558","number":1558,"surah":7,"verses":[206],"verseLabel":"الأعراف: 206","question":"ما دلالة المضارع في ﴿يستكبرون... يسبحونه... يسجدون﴾؟","answer":"يدل على تجدد هذه الأحوال واستمرارها؛ فلا يقع منهم استكبار، ويتكرر تسبيحهم وسجودهم بلا فتور.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص508–520.","url":""}]},{"id":"s7-1559","number":1559,"surah":7,"verses":[206],"verseLabel":"الأعراف: 206","question":"ما مناسبة ختم سورة الأعراف بالسجود بعد افتتاحها بالأمر باتباع الكتاب؟","answer":"افتتحت السورة باتباع الوحي، وختمت بأثر الاتباع وغايته: تنزيه الله والخضوع له وحده؛ فجمع طرفاها بين تلقي الأمر وتحقيق العبودية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص508–520.","url":""}]},{"id":"s8-1","number":1,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"ما مناسبة افتتاح السورة بقوله: ﴿يسألونك عن الأنفال﴾ قبل أن تذكر غزوة بدر وأحداثها؟","answer":"افتتحت السورة بحكم الأنفال قبل تفصيل الوقعة؛ لأن النزاع فيها كان أول ما احتاج إلى الحسم بعد بدر، ولتهيئة النفوس للتسليم لله ورسوله في حكمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص535–536.","url":""}]},{"id":"s8-2","number":2,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿يسألونك﴾، دون أن يقال: «يستفتونك» عن الأنفال؟","answer":"اختير السؤال لما فيه من استعجال المطلوب والتشوف إلى معرفته، بخلاف الاستفتاء الذي يغلب فيه طلب كشف أمر غامض.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص536–537.","url":""}]},{"id":"s8-3","number":3,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"لماذا عُدّي السؤال بـ﴿عن﴾: ﴿يسألونك عن الأنفال﴾، ولم يقل: «يسألونك الأنفال»؟","answer":"عُدّي الفعل بـ﴿عن﴾ لأن سؤالهم كان عن حكم الأنفال ومآلها وقسمتها، لا سؤال طلبٍ للأنفال أنفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص537–538.","url":""}]},{"id":"s8-4","number":4,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"لماذا أُسند السؤال إلى النبي ﷺ بكاف الخطاب: ﴿يسألونك﴾، مع أن الحكم سيأتي من الله؟","answer":"وُجّه السؤال إلى الرسول ﷺ لأنه المبلّغ عن الله والمنفذ لحكمه في الأنفال، ثم جاء الجواب وحيًا من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص536–538.","url":""}]},{"id":"s8-5","number":5,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"لماذا جاء الجواب بالأمر: ﴿قل﴾، ولم يأت الجواب مباشرة: «الأنفال لله والرسول»؟","answer":"جاء ﴿قل﴾ لإظهار أن الجواب المبلّغ حكم من الله لا رأي للنبي ﷺ، وفيه قطع لمادة النزاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص538–539.","url":""}]},{"id":"s8-6","number":6,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿قل﴾ وحذف المخاطبين، فلم يقل: «قل لهم»؟","answer":"حُذف «لهم» للعلم بالمخاطبين من ﴿يسألونك﴾، فاستغنى السياق عنه وجاء التعبير موجزًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص538–539.","url":""}]},{"id":"s8-7","number":7,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"لماذا أعاد لفظ ﴿الأنفال﴾ في الجواب، ولم يقل: «قل هي لله والرسول»؟","answer":"أُعيد لفظ ﴿الأنفال﴾ لتثبيت موضوع الحكم وتعظيم شأنه، ولئلا يوهم الضمير رجوعًا إلى معنى غير مراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص539–540.","url":""}]},{"id":"s8-8","number":8,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"لماذا كانت ﴿الأنفال﴾ في السؤال للعهد بما غنموه، ثم جاء اللفظ نفسه في الجواب عامًا يشمل جنس الأنفال؟","answer":"الأنفال الأولى هي المعهودة التي سألوا عنها يوم بدر، والثانية في مقام بيان الحكم؛ فجاء اللفظ متناولًا لجنس الأنفال، وحكمُه لله والرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص539–540.","url":""}]},{"id":"s8-9","number":9,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿الأنفال لله والرسول﴾، ولم يجعل أمرها للغانمين الذين حصلوها؟","answer":"إضافة حكم الأنفال إلى الله والرسول تنزعها من أهواء الغانمين؛ فقسمتها مردها إلى أمر الله وتنفيذ رسوله، لا إلى مجرد إحراز المقاتلين لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص540–541.","url":""}]},{"id":"s8-10","number":10,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"لماذا اختير اسم الجلالة في ﴿لله﴾، ولم يقل: «للرب»؟","answer":"اختير اسم الجلالة لأنه مقام تشريع وحكم وطاعة، وفيه استحضار الألوهية المستوجبة للامتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص541–542.","url":""}]},{"id":"s8-11","number":11,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿وللرسول﴾، دون أن يقال: «وللنبي»؟","answer":"اختير ﴿الرسول﴾ لأن المقام مقام تبليغ حكم الله وتنفيذه، وهذه جهة الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص542.","url":""}]},{"id":"s8-12","number":12,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"لماذا انتقل من خطاب النبي ﷺ في ﴿يسألونك﴾ إلى وصفه بالغائب: ﴿وللرسول﴾؟","answer":"عُدل من ضمير الخطاب إلى وصف ﴿الرسول﴾ لإبراز علة اختصاصه بالحكم: أنه رسول الله المنفذ لأمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص541–542.","url":""}]},{"id":"s8-13","number":13,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"لماذا فرّع على حكم الأنفال قوله: ﴿فاتقوا الله﴾؟","answer":"فُرّع الأمر بالتقوى على رد الأنفال إلى الله والرسول؛ ليحذروا الطمع والنزاع ومخالفة الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص542–543.","url":""}]},{"id":"s8-14","number":14,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"لماذا ربط التقوى باسم الله: ﴿فاتقوا الله﴾، ولم يقل: «فاتقوا ربكم»؟","answer":"ذكر اسم الله يلائم ما سبق من قوله ﴿الأنفال لله﴾، ويستحضر حق الألوهية في الطاعة وترك التنازع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص543.","url":""}]},{"id":"s8-15","number":15,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"لماذا جمع عقب سؤال الغنائم بين ﴿فاتقوا الله﴾ و﴿أصلحوا ذات بينكم﴾؟","answer":"التقوى تصلح باطن الفرد، وإصلاح ذات البين يزيل أثر الطمع والخصام من الجماعة؛ وهما لازمان في حال الحرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص543–544.","url":""}]},{"id":"s8-16","number":16,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿أصلحوا ذات بينكم﴾، دون أن يقال ببساطة: «أصلحوا بينكم»؟","answer":"﴿ذات بينكم﴾ هي حقيقة الحال والرابطة القائمة بينكم؛ فالأمر يتناول إصلاح الصلة نفسها وحفظ المودة والوحدة، وهو أبلغ من مجرد تسكين خصومة عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص544–546.","url":""}]},{"id":"s8-17","number":17,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"ما مناسبة مجيء الأمر بالطاعة بعد التقوى والإصلاح: ﴿وأطيعوا الله ورسوله﴾؟","answer":"جاء الأمر بالطاعة جامعًا لما تقدمه: قبول حكم الأنفال، والتقوى، وإصلاح ذات البين؛ فكلها امتثال لله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص546–547.","url":""}]},{"id":"s8-18","number":18,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"لماذا أعاد اسمي ﴿الله ورسوله﴾ في الأمر بالطاعة، ولم يقل: «وأطيعوهما»؟","answer":"أُظهر الاسمان بدل الضمير لتعظيم المأمور بطاعتهما، وللتنبيه إلى أن طاعة الرسول من طاعة الله مع بقاء جهة كل منهما ظاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص547–549.","url":""}]},{"id":"s8-19","number":19,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿وأطيعوا الله ورسوله﴾ بإفراد «رسوله»، مع أن الخطاب لجماعة المؤمنين في كل زمان؟","answer":"أُفرد ﴿رسوله﴾ لأن المراد الرسول المعهود المبلّغ عن الله ﷺ، ولأن وحدة مصدر البلاغ والطاعة ثابتة لا تتعدد بتعدد المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص547–549.","url":""}]},{"id":"s8-20","number":20,"surah":8,"verses":[1],"verseLabel":"الأنفال: 1","question":"لماذا علّق الأمر بقوله: ﴿إن كنتم مؤمنين﴾، مع أنه خاطبهم على أنهم مؤمنون؟","answer":"التعليق بـ﴿إن كنتم مؤمنين﴾ حث على تحقيق مقتضى الإيمان؛ فالإيمان الصادق يحمل على الطاعة وترك التنازع، وليس المقصود نفي أصل إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص549–550.","url":""}]},{"id":"s8-21","number":21,"surah":8,"verses":[2],"verseLabel":"الأنفال: 2","question":"لماذا حصر المؤمنين بقوله: ﴿إنما المؤمنون﴾، مع أن الصفات الآتية ليست كل شعب الإيمان؟","answer":"القصر يبين أن أصحاب هذه الصفات هم المؤمنون الكاملون في هذا المقام؛ فالآيات تذكر أصولًا جامعة وآثارًا ظاهرة للإيمان، لا جميع شعبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص551–552.","url":""}]},{"id":"s8-22","number":22,"surah":8,"verses":[2],"verseLabel":"الأنفال: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿إذا ذكر الله وجلت قلوبهم﴾، فجعل الوجل في القلوب لا في النفوس؟","answer":"أُسند الوجل إلى القلوب لأنها محل الشعور الباطن، فدل على خوف عميق نابع من أصل النفس لا مجرد أثر ظاهر في الجوارح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص552–554.","url":""}]},{"id":"s8-23","number":23,"surah":8,"verses":[2],"verseLabel":"الأنفال: 2","question":"لماذا اختير ﴿وجلت﴾ لا «خافت»؟","answer":"اختير الوجل لأنه خوف باطني مصحوب باضطراب وتحرك في القلب، فهو أدق من مطلق الخوف في تصوير تأثر المؤمن بذكر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص553–555.","url":""}]},{"id":"s8-24","number":24,"surah":8,"verses":[2],"verseLabel":"الأنفال: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذا تليت عليهم آياته زادتهم إيمانًا﴾، فنسب الزيادة إلى الآيات؟","answer":"أُسندت الزيادة إلى الآيات لأنها سببها المباشر عند التلاوة؛ بما تكشفه من معان ودلائل تجدد التصديق واليقين والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص555–558.","url":""}]},{"id":"s8-25","number":25,"surah":8,"verses":[2],"verseLabel":"الأنفال: 2","question":"ما وجه زيادة الإيمان بسماع الآيات، مع أن المؤمن كان مؤمنًا قبل تلاوتها؟","answer":"الإيمان يقبل الزيادة من جهة قوة التصديق والطمأنينة وكثرة آثاره العملية؛ فكلما تجددت دلالات الآيات ازداد المؤمن يقينًا واستجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص556–560.","url":""}]},{"id":"s8-26","number":26,"surah":8,"verses":[2],"verseLabel":"الأنفال: 2","question":"لماذا قدّم الجار والمجرور: ﴿وعلى ربهم يتوكلون﴾، ولم يقل: «ويتوكلون على ربهم»؟","answer":"قُدّم ﴿على ربهم﴾ للاختصاص؛ أي يعتمدون على ربهم وحده، لا على الأسباب استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص560–563.","url":""}]},{"id":"s8-27","number":27,"surah":8,"verses":[2],"verseLabel":"الأنفال: 2","question":"لماذا اختير اسم الرب في ﴿على ربهم يتوكلون﴾ بعد ذكر اسم الله في الوجل؟","answer":"اختير ﴿ربهم﴾ لاستحضار رعايته وتدبيره وتربيته لهم، وهي معان تبعث على تفويض الأمر إليه والتوكل عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص562–565.","url":""}]},{"id":"s8-28","number":28,"surah":8,"verses":[3],"verseLabel":"الأنفال: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿يقيمون الصلاة﴾، دون أن يقال: «يصلون»؟","answer":"إقامة الصلاة أداؤها مستقيمة تامة بأركانها وشروطها وخشوعها ودوامها، فهي أبلغ من مجرد وقوع الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص566–568.","url":""}]},{"id":"s8-29","number":29,"surah":8,"verses":[3],"verseLabel":"الأنفال: 3","question":"لماذا قدّم ﴿مما رزقناهم﴾ على ﴿ينفقون﴾؟","answer":"قُدّم ﴿مما رزقناهم﴾ لإبراز أن المنفَق بعض عطاء الله لهم، وفيه تذكير بالمنعم قبل ذكر فعل الإنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص568–570.","url":""}]},{"id":"s8-30","number":30,"surah":8,"verses":[3],"verseLabel":"الأنفال: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿مما رزقناهم﴾ بـ«من» التبعيضية، ولم يأمرهم بإنفاق كل الرزق؟","answer":"دلّت ﴿من﴾ على التبعيض؛ رحمة بالمكلف وإبقاء لما تقوم به مصالحه، فالإنفاق المشروع ليس استغراق المال كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص569–571.","url":""}]},{"id":"s8-31","number":31,"surah":8,"verses":[3],"verseLabel":"الأنفال: 3","question":"لماذا انتقل إلى ضمير العظمة في ﴿رزقناهم﴾؟","answer":"ضمير العظمة في ﴿رزقناهم﴾ يبرز عظمة المنعم وسعة عطائه، ويقرر أن ما ينفقونه إنما هو من رزقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص570–572.","url":""}]},{"id":"s8-32","number":32,"surah":8,"verses":[4],"verseLabel":"الأنفال: 4","question":"لماذا أعاد الإشارة إليهم بقوله: ﴿أولئك هم المؤمنون حقًا﴾ بعد قوله: ﴿إنما المؤمنون﴾؟","answer":"الإشارة بـ﴿أولئك﴾ تجمع أصحاب الصفات السابقة وتميزهم، ثم تقرر لهم حقيقة الإيمان وكماله جزاءً على اجتماعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص573–575.","url":""}]},{"id":"s8-33","number":33,"surah":8,"verses":[4],"verseLabel":"الأنفال: 4","question":"لماذا توسط ضمير الفصل ﴿هم﴾ في ﴿أولئك هم المؤمنون﴾؟","answer":"ضمير الفصل ﴿هم﴾ يقوي الحكم ويفيد قصر كمال الإيمان عليهم في هذا المقام، وينفيه عمن تخلفت عنه تلك الصفات.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص574–576.","url":""}]},{"id":"s8-34","number":34,"surah":8,"verses":[4],"verseLabel":"الأنفال: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿حقًا﴾ بعد هذا التوكيد كله؟","answer":"﴿حقًا﴾ تؤكد أن إيمانهم ثابت متحقق، لا دعوى باللسان ولا وصفًا مجازيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص575–577.","url":""}]},{"id":"s8-35","number":35,"surah":8,"verses":[4],"verseLabel":"الأنفال: 4","question":"لماذا جاءت ﴿درجات﴾ جمعًا، بينما الإيمان الموصوف واحد؟","answer":"جُمعت ﴿درجات﴾ لتفاوت منازل المؤمنين بحسب تفاوتهم في الصفات والأعمال، وإن اشتركوا في أصل الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص577–579.","url":""}]},{"id":"s8-36","number":36,"surah":8,"verses":[4],"verseLabel":"الأنفال: 4","question":"لماذا رتّب الجزاء: ﴿درجات... ومغفرة ورزق كريم﴾ بهذا الترتيب؟","answer":"بدأ بالدرجات وهي رفع المنزلة، ثم بالمغفرة وهي ستر التقصير، ثم بالرزق الكريم وهو تمام الإنعام؛ فجمع الرفعة ودفع الضر وإدامة النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص578–581.","url":""}]},{"id":"s8-37","number":37,"surah":8,"verses":[4],"verseLabel":"الأنفال: 4","question":"لماذا وصف الرزق نفسه بأنه ﴿كريم﴾؟","answer":"وُصف الرزق بالكريم لجمعه النفاسة والهناءة والدوام، ولأنه يصان صاحبه به من كل مهانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص579–581.","url":""}]},{"id":"s8-38","number":38,"surah":8,"verses":[5],"verseLabel":"الأنفال: 5","question":"ما وجه افتتاح قصة الخروج المفاجئ بقوله: ﴿كما أخرجك ربك﴾؛ بماذا يتعلّق التشبيه؟","answer":"التشبيه يربط كراهة بعضهم حكم الأنفال بكراهتهم الخروج للقتال أول الأمر؛ ففي الحالين كان أمر الله حقًا وكانت العاقبة خيرًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص582–585.","url":""}]},{"id":"s8-39","number":39,"surah":8,"verses":[5],"verseLabel":"الأنفال: 5","question":"لماذا أسند الخروج إلى الرب: ﴿أخرجك ربك﴾؟","answer":"إسناد الإخراج إلى ﴿ربك﴾ يشعر بالتدبير والرعاية؛ فالخروج لم يكن مصادفة، بل بتوجيه الرب الذي تولى نصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص584–586.","url":""}]},{"id":"s8-40","number":40,"surah":8,"verses":[5],"verseLabel":"الأنفال: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿من بيتك﴾، دون أن يقال: «من المدينة»؟","answer":"﴿من بيتك﴾ يصور انتقاله ﷺ من موضع السكن والطمأنينة إلى مواجهة غير متوقعة، وهو أخص وأشد تصويرًا من «المدينة».","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص585–588.","url":""}]},{"id":"s8-41","number":41,"surah":8,"verses":[5],"verseLabel":"الأنفال: 5","question":"لماذا قُيّد الإخراج بـ﴿بالحق﴾؟","answer":"قُيّد الخروج بـ﴿بالحق﴾ لبيان أنه جرى بأمر الله ولغاية عادلة، وإن كره فريق ما آل إليه أول الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص587–589.","url":""}]},{"id":"s8-42","number":42,"surah":8,"verses":[5],"verseLabel":"الأنفال: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿فريقًا من المؤمنين﴾، ولم يعمم الكراهة على المؤمنين؟","answer":"قيل ﴿فريقًا﴾ إنصافًا؛ فالكراهة لم تعم المؤمنين، وإنما صدرت من طائفة منهم بسبب ضعف الاستعداد للقتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص589–591.","url":""}]},{"id":"s8-43","number":43,"surah":8,"verses":[6],"verseLabel":"الأنفال: 6","question":"لماذا عبّر بالمضارع: ﴿يجادلونك﴾، مع أن الجدال وقع وانتهى؟","answer":"المضارع يستحضر صورة جدالهم كأنها تقع أمام السامع، ويصور تجدده واستمراره في ذلك الموقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص592–594.","url":""}]},{"id":"s8-44","number":44,"surah":8,"verses":[6],"verseLabel":"الأنفال: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿يجادلونك في الحق﴾، وكيف يجادل المؤمن في حق تبين له؟","answer":"الحق هو الخروج للقاء ذي الشوكة بعد أن ظهر لهم وجهه، وكان جدالهم ناشئًا من كراهة القتال وقلة الاستعداد، لا من إنكار الحق بعد معرفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص594–596.","url":""}]},{"id":"s8-45","number":45,"surah":8,"verses":[6],"verseLabel":"الأنفال: 6","question":"لماذا شبّههم بمن ﴿يساقون إلى الموت﴾، ولم يقل: كأنهم ذاهبون إليه؟","answer":"اختير ﴿يساقون﴾ لتصوير شدة كراهتهم واضطرارهم إلى ما يخافون، كمن يدفع إلى الموت دفعًا لا يملك معه رجوعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص596–599.","url":""}]},{"id":"s8-46","number":46,"surah":8,"verses":[6],"verseLabel":"الأنفال: 6","question":"لماذا بُني ﴿يساقون﴾ للمجهول؟","answer":"بُني ﴿يساقون﴾ للمجهول لأن المقصود تصوير حال المسوقين وقهرهم، لا تعيين السائق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص598–600.","url":""}]},{"id":"s8-47","number":47,"surah":8,"verses":[6],"verseLabel":"الأنفال: 6","question":"لماذا ختم التشبيه بقوله: ﴿وهم ينظرون﴾، وحذف ما ينظرون إليه؟","answer":"﴿وهم ينظرون﴾ يزيد الصورة رهبة؛ فهم يعاينون أسباب الموت أمامهم، وحُذف المفعول لتذهب النفس في تصور ما يرونه من الهول كل مذهب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص600–602.","url":""}]},{"id":"s8-48","number":48,"surah":8,"verses":[7],"verseLabel":"الأنفال: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿إحدى الطائفتين﴾، ولم يسم العير والنفير صراحة؟","answer":"أُبهمت الطائفتان أولًا لأن موضع الامتنان هو الوعد بإحداهما، ولتهيئة السياق للمقابلة بين ذات الشوكة وغير ذات الشوكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص603–605.","url":""}]},{"id":"s8-49","number":49,"surah":8,"verses":[7],"verseLabel":"الأنفال: 7","question":"لماذا عبّر عن العير بـ﴿غير ذات الشوكة﴾؟","answer":"عُبر عن العير بـ﴿غير ذات الشوكة﴾؛ لأن الشوكة كناية عن القوة والسلاح، فدل التعبير على سهولة أخذها وقلة منعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص605–607.","url":""}]},{"id":"s8-50","number":50,"surah":8,"verses":[7],"verseLabel":"الأنفال: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿تكون لكم﴾، دون أن يقال: «تأخذونها»؟","answer":"﴿تكون لكم﴾ أوسع من «تأخذونها»؛ إذ تفيد صيرورتها خالصة لهم وتمكنهم منها، لا مجرد فعل الأخذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص606–608.","url":""}]},{"id":"s8-51","number":51,"surah":8,"verses":[7],"verseLabel":"الأنفال: 7","question":"لماذا قابل إرادة المؤمنين السهولة بقوله: ﴿ويريد الله أن يحق الحق﴾؟","answer":"قوبلت إرادتهم العاجلة للعير السهلة بإرادة الله إظهار الحق؛ لبيان أن اختياره لهم أعظم عاقبة من اختيارهم لأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص608–610.","url":""}]},{"id":"s8-52","number":52,"surah":8,"verses":[7],"verseLabel":"الأنفال: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿يحق الحق بكلماته﴾، فجعل للحق إحقاقًا وهو حق أصلًا؟","answer":"إحقاق الحق إظهاره وإثباته وتغليبه في الواقع؛ فالحق ثابت في ذاته، لكنه يحتاج إلى إظهار سلطانه وإبطال ما ينازعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص609–612.","url":""}]},{"id":"s8-53","number":53,"surah":8,"verses":[7],"verseLabel":"الأنفال: 7","question":"ما الصورة في قوله: ﴿ويقطع دابر الكافرين﴾؟","answer":"في ﴿يقطع دابر الكافرين﴾ استعارة تمثّل استئصال قوتهم بقطع آخرهم وأصل امتدادهم، فلا يبقى لهم أثر مؤثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص611–613.","url":""}]},{"id":"s8-54","number":54,"surah":8,"verses":[8],"verseLabel":"الأنفال: 8","question":"لماذا تكرر ﴿ليحق الحق﴾ بعد ذكره في الآية السابقة؟","answer":"الأول متعلق بإرادة الله اختيار المواجهة ذات الشوكة، والثاني تعليل لما جرى من النصر؛ فتكراره يثبت أن الغاية إظهار الحق لا مجرد إحراز الغنيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص614–616.","url":""}]},{"id":"s8-55","number":55,"surah":8,"verses":[8],"verseLabel":"الأنفال: 8","question":"لماذا قابل ﴿يحق الحق﴾ بـ﴿يبطل الباطل﴾، ولم يقل: يهزم الكافرين؟","answer":"قوبل الحق بالباطل لأن المقصود أوسع من هزيمة قوم: إثبات دين الله وإسقاط الشرك وحججه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص615–617.","url":""}]},{"id":"s8-56","number":56,"surah":8,"verses":[8],"verseLabel":"الأنفال: 8","question":"لماذا وصف المعاندين هنا بـ﴿المجرمون﴾ لا «الكافرون»؟","answer":"وصفهم بالمجرمين يبرز أن عنادهم فعل مكتسب وجناية تستحق الإبطال والعقوبة، لا مجرد وصف اعتقادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص617–618.","url":""}]},{"id":"s8-57","number":57,"surah":8,"verses":[9],"verseLabel":"الأنفال: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿إذ تستغيثون ربكم﴾، دون أن يقال: «إذ تدعون الله»؟","answer":"الاستغاثة طلب الغوث عند الشدة، فهي تصور اضطرار المؤمنين وخطر الموقف، وذكر ﴿ربكم﴾ يستحضر رعايته ونصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص619–622.","url":""}]},{"id":"s8-58","number":58,"surah":8,"verses":[9],"verseLabel":"الأنفال: 9","question":"لماذا جاء جواب الاستغاثة سريعًا بالفاء: ﴿فاستجاب لكم﴾؟","answer":"الفاء تفيد سرعة ترتب الاستجابة على الاستغاثة، فتوحي بقرب الإغاثة وعناية الله بالمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص621–623.","url":""}]},{"id":"s8-59","number":59,"surah":8,"verses":[9],"verseLabel":"الأنفال: 9","question":"لماذا عبّر بـ﴿ممدكم﴾، لا «مرسل إليكم»؟","answer":"الإمداد إلحاق مدد يقوي الموجود ويتتابع عليه، فهو أنسب بحال جيش يحتاج إلى ما يعززه من مجرد الإرسال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص623–625.","url":""}]}]);
